115	
116	      if (result.status === ExecutionStatus.FAILED) {
117	        finalStatus = ExecutionStatus.FAILED;
118	        break;
119	      }
120	      runs.push({
121	        nodeId: node.id,
122	        nodeName: typeof node.data.name === 'string' ? node.data.name : node.id,
123	        input: items,
124	        output: result.output,
125	      });
126	      items = result.output;
127	    }
128	
129	    const finishedAt = new Date();
130	    await this.repository.finishExecution(
131	      executionId,
132	      finalStatus,
133	      finishedAt,
134	      finishedAt.getTime() - startedAt.getTime(),
135	    );
136	
137	    return this.repository.findExecutionResult(executionId);
138	  }
139	}
