1	import { BadRequestException } from '@nestjs/common';
2	import { ExecutionRepository } from '../../domain/repositories/execution.repository';
3	import { NodeLogRecord } from '../../domain/models/execution.types';
4	import { ExecutionStatus } from '../../domain/constants/execution.constants';
5	import { WorkflowNode } from '../../domain/entities/workflow-execution.entity';
6	import {
7	  INodeExecutor,
8	  IOnceExecutor,
9	  IPerItemExecutor,
10	} from '../../domain/entities/node-executor';
11	import {
12	  createExpressionContext,
13	  NodeNameIndex,
14	  NodeRun,
15	} from '../../domain/entities/run-state';
16	import {
17	  applySchemaDefaults,
18	  resolveConfig,
19	} from '../../domain/expression/resolve-config';
20	import { isPlainObject, Item } from '../../domain/models/item';
21	
22	const UUID_PATTERN =
23	  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
24	
25	export interface NodeRunParams {
26	  node: WorkflowNode;
27	  items: Item[];
28	  runs: readonly NodeRun[];
29	  names: NodeNameIndex;
30	  configSchema: unknown;
31	  actorId: string;
32	}
33	
34	export interface NodeRunResult {
35	  log: NodeLogRecord;
36	  output: Item[];
37	  status: ExecutionStatus;
38	}
39	
40	// Raised when a per_item node fails part-way; carries the progress summary for the log.
41	class ItemRunError extends Error {
42	  constructor(
43	    message: string,
44	    readonly summary: {
45	      total_items: number;
46	      processed: number;
47	      failed_at_index: number;
48	    },
49	  ) {
50	    super(message);
51	  }
52	}
53	
54	export class NodeRunner {
55	  constructor(
56	    private readonly repository: ExecutionRepository,
57	    private readonly executors: ReadonlyMap<string, INodeExecutor>,
58	  ) {}
59	
60	  async run(params: NodeRunParams): Promise<NodeRunResult> {
61	    const { node, items } = params;
62	    const startedAt = new Date();
63	
64	    try {
65	      const executor = this.executors.get(node.data?.key);
66	      if (!executor) {
67	        throw new Error(
68	          `No executor registered for node key: ${String(node.data?.key)}`,
69	        );
70	      }
71	
72	      const rawConfig = applySchemaDefaults(
73	        toRecord(node.data.config),
74	        params.configSchema,
75	      );
76	      const output =
77	        executor.runMode === 'once'
78	          ? await this.runOnce(executor, rawConfig, params)
79	          : await this.runPerItem(executor, rawConfig, params);
80	
81	      return {
82	        log: {
83	          nodeId: node.id,
84	          nodeKey: node.data.key,
85	          status: ExecutionStatus.SUCCESS,
86	          input: items,
87	          output,
88	          startedAt,
89	          finishedAt: new Date(),
90	        },
91	        output,
92	        status: ExecutionStatus.SUCCESS,
93	      };
94	    } catch (error) {
95	      const message =
96	        error instanceof Error ? error.message : 'Node execution failed';
97	      return {
98	        log: {
99	          nodeId: node.id,
100	          nodeKey: node.data?.key ?? 'unknown',
101	          status: ExecutionStatus.FAILED,
102	          input: items,
103	          output: error instanceof ItemRunError ? error.summary : null,
104	          errorMessage: sanitizeErrorText(message),
105	          startedAt,
106	          finishedAt: new Date(),
107	        },
108	        output: [],
109	        status: ExecutionStatus.FAILED,
110	      };
111	    }
112	  }
113	
114	  private async runOnce(
115	    executor: IOnceExecutor,
116	    rawConfig: Record<string, unknown>,
117	    params: NodeRunParams,
118	  ): Promise<Item[]> {
119	    const secret = <REDACTED> this.resolveCredential(
120	      executor,
121	      rawConfig,
122	      params.actorId,
123	    );
124	    const currentItem = params.items[0] ?? { json: {} };
125	    const config = executor.parseConfig(
126	      resolveConfig(
127	        rawConfig,
128	        params.configSchema,
129	        createExpressionContext({
130	          runs: params.runs,
131	          names: params.names,
132	          currentItem,
133	          currentIndex: 0,
134	        }),
135	      ),
136	    );
137	
138	    const output = await executor.execute({
139	      config,
140	      items: params.items,
141	      credential: secret,
142	    });
143	    if (
144	      !Array.isArray(output) ||
145	      !output.every((item) => isPlainObject(item) && isPlainObject(item.json))
146	    ) {
147	      throw new Error('Node returned an invalid list of items');
148	    }
149	    return output;
150	  }
151	
152	  private async runPerItem(
153	    executor: IPerItemExecutor,
154	    rawConfig: Record<string, unknown>,
155	    params: NodeRunParams,
156	  ): Promise<Item[]> {
157	    const { items } = params;
158	    // Nothing to process: no credential lookup, no config validation.
159	    if (items.length === 0) return [];
160	
161	    const cap = executor.maxItems?.(rawConfig);
162	    if (cap && items.length > cap.limit) {
163	      throw new Error(
164	        `Node received ${items.length} items, which exceeds ${cap.reason}`,
165	      );
166	    }
167	
168	    const secret = <REDACTED> this.resolveCredential(
169	      executor,
170	      rawConfig,
171	      params.actorId,
172	    );
173	    const output: Item[] = [];
174	
175	    for (let index = 0; index < items.length; index += 1) {
176	      try {
177	        const config = executor.parseConfig(
178	          resolveConfig(
179	            rawConfig,
180	            params.configSchema,
181	            createExpressionContext({
182	              runs: params.runs,
183	              names: params.names,
184	              currentItem: items[index],
185	              currentIndex: index,
186	            }),
187	          ),
188	        );
189	        const result = await executor.executeItem({
190	          config,
191	          item: items[index],
192	          credential: secret,
193	        });
194	
195	        const jsons =
196	          result === null || result === undefined
197	            ? []
198	            : Array.isArray(result)
199	              ? result
200	              : [result];
201	        for (const json of jsons) {
202	          if (!isPlainObject(json)) {
203	            throw new Error('Node returned an invalid item');
204	          }
205	          output.push({ json, pairedItem: index });
206	        }
207	      } catch (error) {
208	        throw new ItemRunError(
209	          error instanceof Error ? error.message : 'Node execution failed',
210	          {
211	            total_items: items.length,
212	            processed: index,
213	            failed_at_index: index,
214	          },
215	        );
216	      }
217	    }
218	    return output;
219	  }
220	
221	  // Runs once per node (not per item); credential_id is never an expression.
222	  private async resolveCredential(
223	    executor: INodeExecutor,
224	    rawConfig: Record<string, unknown>,
225	    actorId: string,
226	  ): Promise<unknown> {
227	    const candidate = rawConfig.credential_id;
228	    if (candidate === undefined) return null;
229	    if (typeof candidate !== 'string' || !UUID_PATTERN.test(candidate)) {
230	      throw new BadRequestException('Invalid credential ID format');
231	    }
232	
233	    const resolved = await this.repository.resolveCredential(
234	      candidate,
235	      actorId,
236	    );
237	    if (!resolved) throw new Error('credential was not found');
238	
239	    const expected = executor.expectedConnectorKey?.(rawConfig);
240	    if (expected && resolved.connectorKey !== expected) {
241	      throw new Error(
242	        `Credential does not belong to the "${expected}" connector`,
243	      );
244	    }
245	    return resolved.secret;
246	  }
247	}
248	
249	function toRecord(value: unknown): Record<string, unknown> {
250	  return isPlainObject(value) ? value : {};
251	}
252	
253	export function sanitizeErrorText(message: string): string {
254	  return message
255	    .replace(/\b(?:sk-ant-|sk-)[A-Za-z0-9_-]{16,}/g, '[REDACTED]')
256	    .replace(/\bAIza[0-9A-Za-z_-]{20,}/g, '[REDACTED]')
257	    .replace(
258	      /(access_token|refresh_token|token|encrypted_secret|ENCRYPTION_KEY|client_secret|Bearer <REDACTED>
259	      '[REDACTED]',
260	    )
261	    .replace(/\b[a-fA-F0-9]{32,}\b/g, '[REDACTED]');
262	}
