19	@Injectable()
20	export class PrismaExecutionRepository implements ExecutionRepository {
21	  constructor(private readonly prisma: PrismaService) {}
22	
23	  async findVersion(id: string): Promise<WorkflowVersionForExecution | null> {
24	    const row = await this.prisma.workflowVersion.findUnique({
25	      where: { id },
26	      include: { workflow: { select: { ownerId: true } } },
27	    });
28	    if (!row) return null;
29	    return {
30	      id: row.id,
31	      workflowId: row.workflowId,
32	      definition: row.definition,
33	      workflowOwnerId: row.workflow.ownerId,
34	    };
35	  }
36	
37	  async createExecution(input: Omit<ExecutionRecord, 'id'>): Promise<string> {
38	    const row = await this.prisma.execution.create({
39	      data: {
40	        workflowId: input.workflowId,
41	        workflowVersionId: input.workflowVersionId,
42	        triggerType: 'MANUAL',
43	        triggeredById: input.triggeredById,
44	        status: ExecutionStatus.RUNNING,
45	        startedAt: input.startedAt,
46	      },
47	      select: { id: true },
48	    });
49	    return row.id;
50	  }
51	
52	  async resolveCredential(
53	    credentialId: string,
54	    ownerId: string,
55	  ): Promise<ResolvedCredential> {
56	    const credential = await this.prisma.connectorCredential.findUnique({
57	      where: { id: credentialId },
58	      include: { connector: true },
59	    });
60	    if (!credential) {
61	      throw new Error('credential was not found');
62	    }
63	    if (credential.ownerId !== ownerId) {
64	      throw new Error('credential does not belong to this workflow owner');
65	    }
66	
67	    const encryptionKey = process.env['ENCRYPTION_KEY'];
68	    if (!encryptionKey) {
69	      throw new Error('Credential decryption key is not configured');
70	    }
71	
72	    const plaintext = EncryptionUtil.decrypt(
73	      credential.encryptedSecret,
74	      encryptionKey,
75	    );
76	    return {
77	      connectorKey: credential.connector.key,
78	      secret: <REDACTED> as unknown,
79	    };
80	  }
81	
82	  async saveNodeLog(executionId: string, log: NodeLogRecord): Promise<void> {
83	    await this.prisma.executionNodeLog.create({
84	      data: {
85	        executionId,
86	        nodeId: log.nodeId,
87	        nodeKey: log.nodeKey,
88	        status: log.status,
89	        input: jsonValue(log.input),
90	        output: jsonValue(log.output),
91	        errorMessage: log.errorMessage,
92	        startedAt: log.startedAt,
93	        finishedAt: log.finishedAt,
94	        durationMs: log.finishedAt.getTime() - log.startedAt.getTime(),
95	      },
96	    });
97	  }
98	
99	  async finishExecution(
100	    id: string,
101	    status: ExecutionStatus,
102	    finishedAt: Date,
103	    durationMs: number,
104	  ): Promise<void> {
105	    await this.prisma.execution.update({
106	      where: { id },
107	      data: { status: status, finishedAt, durationMs },
108	    });
109	  }
110	
111	  async findExecutionResult(id: string): Promise<unknown> {
112	    const row = await this.prisma.execution.findUnique({
113	      where: { id },
114	      include: { nodeLogs: { orderBy: { startedAt: 'asc' } } },
115	    });
116	    if (!row) return null;
117	    return {
118	      id: row.id,
119	      status: row.status,
120	      startedAt: row.startedAt,
121	      finishedAt: row.finishedAt,
122	      durationMs: row.durationMs,
123	      nodeLogs: row.nodeLogs.map((log) => ({
124	        id: log.id,
125	        nodeId: log.nodeId,
126	        nodeKey: log.nodeKey,
127	        status: log.status as ExecutionStatus,
128	        input: log.input,
129	        output: log.output,
130	        errorMessage: log.errorMessage,
131	        startedAt: log.startedAt,
132	        finishedAt: log.finishedAt,
133	        durationMs: log.durationMs,
134	      })),
135	    };
136	  }
137	}
