export enum ExecutionStatus {
  RUNNING = 'RUNNING',
  SUCCESS = 'SUCCESS',
  FAILED = 'FAILED',
}

export const NodeKeys = {
  GMAIL_SEND: 'integration.gmail.send',
  GOOGLE_SHEET_READ_ROWS: 'integration.google_sheet.readRows',
  TRIGGER_MANUAL: 'trigger.manual',
  LOGIC_FILTER: 'logic.filter',
  DATA_AGGREGATE: 'data.aggregate',
  AI_LLM_GENERATE: 'ai.llm.generate',
} as const;

export const ConnectorKeys = {
  GOOGLE: 'google',
  ANTHROPIC: 'anthropic',
  OPENAI: 'openai',
  GEMINI: 'gemini',
} as const;

export const LlmLimits = {
  // Ceiling for a node's max_items when the LLM_MAX_ITEMS env var is not set.
  DEFAULT_MAX_ITEMS_CEILING: 100,
  DEFAULT_MAX_ITEMS: 50,
  DEFAULT_MAX_TOKENS: 1024,
  REQUEST_TIMEOUT_MS: 60_000,
  MAX_RETRIES: 2,
} as const;
export interface WorkflowNode {
  id: string;
  data: { key: string; config?: unknown; [key: string]: unknown };
  [key: string]: unknown;
}

export interface WorkflowEdge {
  source: string;
  target: string;
  [key: string]: unknown;
}

export interface WorkflowDefinition {
  nodes: WorkflowNode[];
  edges: WorkflowEdge[];
  [key: string]: unknown;
}

// The edges may be stored in any order (the designer appends them as the user
// draws them), so the chain is rebuilt by following source -> target.
export function getExecutionOrder(definition: unknown): string[] {
  if (!definition || typeof definition !== 'object')
    throw new Error('Workflow definition is invalid');
  const graph = definition as Partial<WorkflowDefinition>;
  if (!Array.isArray(graph.edges) || graph.edges.length === 0)
    throw new Error('Workflow definition must contain a non-empty edge chain');
  if (!Array.isArray(graph.nodes))
    throw new Error('Workflow definition must contain nodes');

  const nextOf = new Map<string, string>();
  const targets = new Set<string>();
  for (const edge of graph.edges) {
    if (
      !edge ||
      typeof edge.source !== 'string' ||
      typeof edge.target !== 'string' ||
      nextOf.has(edge.source) ||
      targets.has(edge.target)
    ) {
      throw new Error('Workflow edges must form a single directed chain');
    }
    nextOf.set(edge.source, edge.target);
    targets.add(edge.target);
  }

  const starts = [...nextOf.keys()].filter((id) => !targets.has(id));
  if (starts.length !== 1) {
    throw new Error('Workflow edges must form a single directed chain');
  }
  const order = [starts[0]];
  for (let next = nextOf.get(starts[0]); next; next = nextOf.get(next)) {
    order.push(next);
  }
  if (order.length !== graph.edges.length + 1) {
    throw new Error('Workflow edges must form a single directed chain');
  }

  const nodesById = new Map(graph.nodes.map((node) => [node.id, node]));
  for (const id of order) {
    if (!nodesById.has(id))
      throw new Error(`Workflow edge references missing node: ${id}`);
  }
  return order;
}
import { Body, Controller, Post, UseGuards } from '@nestjs/common';
import { CommandBus } from '@nestjs/cqrs';
import { ApiBearerAuth, ApiOperation, ApiTags } from '@nestjs/swagger';
import { JwtAuthGuard } from '@app/auth/infrastructure/guards/jwt-auth.guard';
import {
  CurrentUser,
  AuthenticatedUser,
} from '@app/auth/infrastructure/decorators/current-user.decorator';
import { StartExecutionCommand } from '../../application/commands/start-execution/start-execution.command';
import { StartExecutionDto } from './dtos/start-execution.dto';

@ApiTags('executions')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('api/executions')
export class ExecutionController {
  constructor(private readonly commandBus: CommandBus) {}

  @Post()
  @ApiOperation({ summary: 'Run a published workflow version manually' })
  async start(
    @Body() body: StartExecutionDto,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    const result: unknown = await this.commandBus.execute(
      new StartExecutionCommand(body.workflow_version_id, user.id),
    );
    return { success: true, data: result };
  }
}
export * from './execution.module';
