41	export const LLM_CREDENTIAL_ID = '33333333-3333-3333-3333-333333333332';
42	export const LLM_API_KEY = <REDACTED>;
43	
44	export class MemoryExecutionRepository extends ExecutionRepository {
45	  logs: NodeLogRecord[] = [];
46	  finishedStatus: ExecutionStatus | null = null;
47	  // Connector the stored credentials belong to.
48	  connectorKey = 'google';
49	  llmConnectorKey = 'openai';
50	
