52	    super();
53	  }
54	
55	  findVersion(): Promise<WorkflowVersionForExecution | null> {
56	    return Promise.resolve(this.version);
57	  }
58	
59	  createExecution(): Promise<string> {
60	    return Promise.resolve('execution-1');
61	  }
