66	  ): Promise<ResolvedCredential> {
67	    if (ownerId === 'actor-1' && credentialId === CREDENTIAL_ID) {
68	      return Promise.resolve({
69	        connectorKey: this.connectorKey,
70	        secret: <REDACTED>
71	          refresh_token: <REDACTED>,
72	          access_token: <REDACTED>,
73	        },
74	      });
75	    }
76	    if (ownerId === 'actor-1' && credentialId === LLM_CREDENTIAL_ID) {
77	      return Promise.resolve({
78	        connectorKey: this.llmConnectorKey,
79	        secret: <REDACTED> api_key: <REDACTED> },
80	      });
81	    }
82	    return Promise.reject(new Error('credential was not found'));
83	  }
