210	export interface BuildOptions {
211	  rows?: Row[];
212	  send?: jest.Mock;
213	  connectorKey?: string;
214	  llmReplies?: LlmReply[];
215	  llmConnectorKey?: string;
216	  llmCeiling?: number;
217	  catalog?: NodeCatalogPort;
218	}
