220	export function build(definition: unknown, options: BuildOptions = {}) {
221	  const send =
222	    options.send ?? jest.fn().mockResolvedValue({ data: { id: 'm' } });
223	  const llm = new FakeLlmProvider(options.llmReplies);
224	  const repository = new MemoryExecutionRepository({
225	    id: 'version-1',
226	    workflowId: 'workflow-1',
227	    workflowOwnerId: 'actor-1',
228	    definition,
229	  });
230	  if (options.connectorKey) repository.connectorKey = options.connectorKey;
231	  if (options.llmConnectorKey) {
232	    repository.llmConnectorKey = options.llmConnectorKey;
233	  }
234	
235	  const handler = new StartExecutionHandler(
236	    repository,
237	    [
238	      new ManualTriggerExecutor(),
239	      new GoogleSheetReadRowsExecutor(() => ({
240	        spreadsheets: {
241	          values: {
242	            get: jest.fn().mockResolvedValue({
243	              data: { values: options.rows ?? CUSTOMERS },
244	            }),
245	          },
246	        },
247	      })),
248	      new FilterExecutor(),
249	      new GmailSendExecutor(() => ({ users: { messages: { send } } })),
250	      new AggregateExecutor(),
251	      new LlmGenerateExecutor(
252	        new LlmProviderRegistry([llm]),
253	        options.llmCeiling ?? 500,
254	        () => Promise.resolve(),
255	      ),
256	    ],
257	    options.catalog ?? new FakeCatalog(),
258	  );
259	
260	  const run = async () =>
261	    (await handler.execute(
262	      new StartExecutionCommand('version-1', 'actor-1'),
263	    )) as {
264	      nodeLogs: NodeLogRecord[];
265	      status: ExecutionStatus;
266	    };
267	  return { run, send, llm };
268	}
269	
270	export const logOf = (nodeLogs: NodeLogRecord[], key: string) =>
271	  nodeLogs.find((log) => log.nodeKey === key);
272	
273	export const jsonOf = (value: unknown) =>
274	  (value as Item[]).map((item) => item.json);
275	
276	export const decode = (send: jest.Mock, call: number): string => {
277	  const calls = send.mock.calls as Array<[{ requestBody: { raw: string } }]>;
278	  return Buffer.from(calls[call][0].requestBody.raw, 'base64url').toString();
279	};
