    'system_prompt',
    'prompt',
    'output_format',
    'max_tokens',
    'temperature',
    'max_items',
  ],
  properties: {
    provider: {
      type: 'string',
      title: 'Provider',
      enum: ['anthropic', 'openai', 'gemini'],
    },
    credential_id: {
      type: 'string',
      title: 'Credential',
      'x-refType': 'credential',
