      type: 'string',
      title: 'Model',
      // Grey hint in the box; models change often, so it is free text, not a list.
      'x-placeholderByField': {
        field: 'provider',
        values: {
          anthropic: 'e.g. claude-opus-5-5',
          openai: 'e.g. gpt-4o-mini',
          gemini: 'e.g. gemini-2.0-flash',
        },
      },
    },
    system_prompt: {
      type: 'string',
      title: 'System prompt',
