    startedAt: Date,
  ): Promise<ExecutionStatus> {
    let finalStatus = ExecutionStatus.SUCCESS;
    try {
      finalStatus = await this.runNodes(executionId, version, triggerItems);
    } finally {
      const finishedAt = new Date();
      await this.repository.finishExecution(
        executionId,
        // An unexpected error (e.g. the database) must not leave it RUNNING.
        finalStatus === ExecutionStatus.SUCCESS && !this.completed
          ? ExecutionStatus.FAILED
