      // sent emails or messages.
      attempts: 1,
      removeOnComplete: 1000,
      removeOnFail: 1000,
    },
  }),
];

@Injectable()
export class BullMqExecutionQueue implements ExecutionQueuePort {
  constructor(@InjectQueue(EXECUTION_QUEUE) private readonly queue: Queue) {}

