import { randomBytes } from 'node:crypto';

export enum TriggerChannel {
  WEBHOOK = 'WEBHOOK',
  MESSENGER = 'MESSENGER',
  ZALO_OA = 'ZALO_OA',
}

export const TriggerKeys = {
  WEBHOOK: 'trigger.webhook',
} as const;

// Node keys that make a published version listen for outside events.
const CHANNEL_BY_KEY: Record<string, TriggerChannel> = {
  [TriggerKeys.WEBHOOK]: TriggerChannel.WEBHOOK,
};

export interface WorkflowTrigger {
  id: string;
  workflowId: string;
  workflowVersionId: string;
  nodeId: string;
  triggerKey: string;
  channel: TriggerChannel;
  // WEBHOOK: secret token in the URL. Later channels: page / OA id.
  routingKey: string;
  isActive: boolean;
  createdAt: Date;
}

export type NewWorkflowTrigger = Pick<
  WorkflowTrigger,
  'nodeId' | 'triggerKey' | 'channel' | 'routingKey'
>;

export interface TriggerNode {
  nodeId: string;
  triggerKey: string;
  channel: TriggerChannel;
}

// Trigger nodes of a definition that need a listener (manual triggers don't).
export function findTriggerNodes(definition: unknown): TriggerNode[] {
  const nodes = (definition as { nodes?: unknown } | null)?.nodes;
  if (!Array.isArray(nodes)) return [];

  const found: TriggerNode[] = [];
  for (const node of nodes as Array<{ id?: unknown; data?: { key?: unknown } }>) {
    const key = node?.data?.key;
    if (typeof node?.id !== 'string' || typeof key !== 'string') continue;
    const channel = CHANNEL_BY_KEY[key];
    if (channel) found.push({ nodeId: node.id, triggerKey: key, channel });
  }
  return found;
}

// Plans the listeners for a newly published version. A webhook node keeps the
// token it had in earlier versions, so its URL survives re-publishing.
export function planTriggers(
  triggerNodes: TriggerNode[],
  previous: readonly WorkflowTrigger[],
  newToken: <REDACTED> => string = generateWebhookToken,
): NewWorkflowTrigger[] {
  return triggerNodes.map((node) => {
    const earlier = previous
      .filter((t) => t.nodeId === node.nodeId && t.channel === node.channel)
      .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())[0];
    return {
      ...node,
      routingKey: earlier?.routingKey ?? newToken(),
    };
  });
}

export function generateWebhookToken(): string {
  return randomBytes(32).toString('base64url');
}

// Credentials of the caller must not end up in execution logs.
const HIDDEN_HEADERS = new Set([
  'authorization',
  'proxy-authorization',
  'cookie',
  'x-api-key',
]);

export interface WebhookRequest {
  body: unknown;
  query: Record<string, unknown>;
  headers: Record<string, string | string[] | undefined>;
}

// The single item a webhook call feeds into the workflow.
export function buildWebhookItem(
  request: WebhookRequest,
  receivedAt: Date,
): { json: Record<string, unknown> } {
  const headers: Record<string, string> = {};
  for (const [name, value] of Object.entries(request.headers)) {
    if (value === undefined || HIDDEN_HEADERS.has(name.toLowerCase())) continue;
    headers[name.toLowerCase()] = Array.isArray(value) ? value.join(', ') : value;
  }
  return {
    json: {
      body: request.body ?? null,
      query: request.query,
      headers,
      received_at: receivedAt.toISOString(),
    },
  };
}

import {
  NewWorkflowTrigger,
  TriggerChannel,
  WorkflowTrigger,
} from './workflow-trigger';

export abstract class WorkflowTriggerRepository {
  abstract findActive(
    channel: TriggerChannel,
    routingKey: string,
  ): Promise<WorkflowTrigger | null>;
  // Every row of the workflow, active or not (to reuse webhook tokens).
  abstract findByWorkflow(workflowId: string): Promise<WorkflowTrigger[]>;
  // In one transaction: deactivate the workflow's listeners, add the new ones.
  abstract replaceActive(
    workflowId: string,
    workflowVersionId: string,
    triggers: NewWorkflowTrigger[],
  ): Promise<void>;
  abstract findWorkflowOwnerId(workflowId: string): Promise<string | null>;
}

export abstract class WebhookDedupPort {
  // True the first time a key is seen within the TTL, false for repeats.
  abstract claim(key: string, ttlSeconds: number): Promise<boolean>;
}

