        triggerKey: trigger.triggerKey,
        channel: trigger.channel,
        webhookUrl:
          trigger.channel === TriggerChannel.WEBHOOK
            ? `${publicBaseUrl()}/api/webhooks/w/${trigger.routingKey}`
            : null,
      }));
  }
}

