import {
  Body,
  Controller,
  Headers,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Query,
  Req,
} from '@nestjs/common';
import { CommandBus } from '@nestjs/cqrs';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import type { Request } from 'express';
import {
  ReceiveWebhookCommand,
  ReceiveWebhookResult,
} from '../../application/commands/receive-webhook.command';

// Public: callers are not FlowPilot users. The secret token in the URL is the
// only credential, so no JWT guard here.
@ApiTags('webhooks')
@Controller('api/webhooks')
export class WebhooksController {
  constructor(private readonly commandBus: CommandBus) {}

  @Post('w/:token')
  @HttpCode(HttpStatus.ACCEPTED)
  @ApiOperation({
    summary: 'Start the workflow listening on this webhook URL',
  })
  async receive(
    @Param('token') token: <REDACTED>,
    @Body() body: unknown,
    @Query() query: Record<string, unknown>,
    @Req() request: Request,
    @Headers('idempotency-key') idempotencyKey?: string,
  ) {
    const result = await this.commandBus.execute<
      ReceiveWebhookCommand,
      ReceiveWebhookResult
    >(
      new ReceiveWebhookCommand(
        token,
        { body, query, headers: request.headers },
        idempotencyKey?.trim() || undefined,
      ),
    );
    return { success: true, data: result };
  }
}

import { Controller, Get, Param, ParseUUIDPipe, UseGuards } from '@nestjs/common';
import { QueryBus } from '@nestjs/cqrs';
import { ApiBearerAuth, ApiOperation, ApiTags } from '@nestjs/swagger';
import { JwtAuthGuard } from '@app/auth/infrastructure/guards/jwt-auth.guard';
import {
  CurrentUser,
  AuthenticatedUser,
} from '@app/auth/infrastructure/decorators/current-user.decorator';
import {
  GetWorkflowTriggersQuery,
  WorkflowTriggerView,
} from '../../application/queries/get-workflow-triggers.query';

@ApiTags('workflows')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('api/workflows')
export class WorkflowTriggersController {
  constructor(private readonly queryBus: QueryBus) {}

  @Get(':id/triggers')
  @ApiOperation({
    summary: 'Listeners (e.g. webhook URLs) of the published version',
  })
  async list(
    @Param('id', ParseUUIDPipe) workflowId: string,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    const triggers = await this.queryBus.execute<
      GetWorkflowTriggersQuery,
      WorkflowTriggerView[]
    >(new GetWorkflowTriggersQuery(workflowId, user.id));
    return { success: true, data: triggers };
  }
}

import { Module } from '@nestjs/common';
import { CqrsModule } from '@nestjs/cqrs';
import { PrismaModule } from '@app/database';
import { AuthModule } from '@app/auth';
import { WebhooksController } from './presentation/http/webhooks.controller';
import { WorkflowTriggersController } from './presentation/http/workflow-triggers.controller';
import { SyncWorkflowTriggersHandler } from './application/events/sync-workflow-triggers.handler';
import { ReceiveWebhookHandler } from './application/commands/receive-webhook.command';
import { GetWorkflowTriggersHandler } from './application/queries/get-workflow-triggers.query';
import { WebhookDedupPort } from './application/ports/webhook-dedup.port';
import { WorkflowTriggerRepository } from './domain/workflow-trigger.repository';
import { PrismaWorkflowTriggerRepository } from './infrastructure/prisma-workflow-trigger.repository';
import { RedisWebhookDedup } from './infrastructure/redis-webhook-dedup';

@Module({
  imports: [CqrsModule, PrismaModule, AuthModule],
  controllers: [WebhooksController, WorkflowTriggersController],
  providers: [
    SyncWorkflowTriggersHandler,
    ReceiveWebhookHandler,
    GetWorkflowTriggersHandler,
    {
      provide: WorkflowTriggerRepository,
      useClass: PrismaWorkflowTriggerRepository,
    },
    { provide: WebhookDedupPort, useClass: RedisWebhookDedup },
  ],
})
export class TriggersModule {}

