} from '../../application/queries/get-workflow-triggers.query';

@ApiTags('workflows')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('api/workflows')
export class WorkflowTriggersController {
  constructor(private readonly queryBus: QueryBus) {}

  @Get(':id/triggers')
