// A listener of the published version (e.g. a webhook URL).
export interface WorkflowTrigger {
  nodeId: string;
  triggerKey: string;
  channel: 'WEBHOOK' | 'MESSENGER' | 'ZALO_OA';
  // Only this version receives events.
  workflowVersionId: string;
  webhookUrl: string | null;
}

import { apiClient } from '../../../shared/api/http-client';
import type { WorkflowTrigger } from '../types/trigger.types';

export const triggerApi = {
  list: async (workflowId: string): Promise<WorkflowTrigger[]> => {
    const res = await apiClient.get<{ data: WorkflowTrigger[] }>(
      `/api/workflows/${workflowId}/triggers`,
    );
    return res.data.data;
  },
};

import { triggerApi } from '../api/trigger.api';
import type { WorkflowTrigger } from '../types/trigger.types';

export const triggerService = {
  list: (workflowId: string): Promise<WorkflowTrigger[]> => triggerApi.list(workflowId),

  // Listener of a node, if the node belongs to the published version.
  findForNode: (triggers: WorkflowTrigger[] | undefined, nodeId: string) =>
    triggers?.find((trigger) => trigger.nodeId === nodeId),
};

import { useQuery } from '@tanstack/react-query';
import { triggerService } from '../services/trigger.service';
import type { WorkflowTrigger } from '../types/trigger.types';

export const triggerKeys = {
  all: ['workflow-triggers'] as const,
  list: (workflowId: string) => [...triggerKeys.all, workflowId] as const,
};

export function useWorkflowTriggers(workflowId: string | undefined, enabled = true) {
  return useQuery<WorkflowTrigger[]>({
    queryKey: triggerKeys.list(workflowId ?? ''),
    queryFn: () => triggerService.list(workflowId as string),
    enabled: !!workflowId && enabled,
  });
}

