import { BadRequestException, NotFoundException } from '@nestjs/common';
import { CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { EncryptionUtil } from '@app/shared/utils/encryption.util';
import { ConnectorRepository } from '../../domain/repositories/connector.repository';
import { ConnectorCredentialRepository } from '../../domain/repositories/connector-credential.repository';
import { ConnectorCredential } from '../../domain/entities/connector-credential.entity';
import { ConnectorAuthType } from '../../domain/enums/connector-auth-type.enum';
import { CredentialSummary } from '../dtos/credential-summary.dto';

export class CreateApiKeyCredentialCommand {
  constructor(
    readonly connectorKey: string,
    readonly ownerId: string,
    readonly name: string,
    readonly apiKey: <REDACTED>,
  ) {}
}

@CommandHandler(CreateApiKeyCredentialCommand)
export class CreateApiKeyCredentialHandler implements ICommandHandler<CreateApiKeyCredentialCommand> {
  constructor(
    private readonly connectorRepo: ConnectorRepository,
    private readonly credentialRepo: ConnectorCredentialRepository,
  ) {}

  async execute(
    command: CreateApiKeyCredentialCommand,
  ): Promise<CredentialSummary> {
    const connector = await this.connectorRepo.findByKey(command.connectorKey);
    if (!connector || !connector.isActive) {
      throw new NotFoundException(
        `Connector "${command.connectorKey}" was not found`,
      );
    }
    if (connector.authType !== ConnectorAuthType.API_KEY) {
      throw new BadRequestException(
        `Connector "${connector.key}" does not use an API key`,
      );
    }

    const name = command.name.trim();
    const apiKey = <REDACTED>;
    if (!name || !apiKey) {
      throw new BadRequestException('name and api_key must not be blank');
    }

    const encryptionKey = process.env['ENCRYPTION_KEY'];
    if (!encryptionKey) {
      throw new Error('ENCRYPTION_KEY is not defined');
    }

    const saved = await this.credentialRepo.create(
      new ConnectorCredential(
        undefined,
        connector.id,
        command.ownerId,
        name,
        EncryptionUtil.encrypt(
          JSON.stringify({ api_key: <REDACTED> }),
          encryptionKey,
        ),
      ),
    );

    return {
      id: saved.id!,
      connectorKey: connector.key,
      name: saved.name,
      createdAt: saved.createdAt!,
    };
  }
}
import { Body, Controller, Get, Param, Post, UseGuards } from '@nestjs/common';
import { CommandBus, QueryBus } from '@nestjs/cqrs';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBearerAuth,
} from '@nestjs/swagger';
import { GetConnectorsQuery } from '../../application/queries/get-connectors.query';
import { ListCredentialsQuery } from '../../application/queries/list-credentials.query';
import { CreateApiKeyCredentialCommand } from '../../application/commands/create-api-key-credential.command';
import { CredentialSummary } from '../../application/dtos/credential-summary.dto';
import { JwtAuthGuard } from '../../../../auth/src/infrastructure/guards/jwt-auth.guard';
import {
  AuthenticatedUser,
  CurrentUser,
} from '../../../../auth/src/infrastructure/decorators/current-user.decorator';
import { Connector } from '../../domain/entities/connector.entity';
import { ConnectorResponseDto } from './dtos/connector-response.dto';
import { CreateApiKeyCredentialDto } from './dtos/create-api-key-credential.dto';
import { CredentialResponseDto } from './dtos/credential-response.dto';

@ApiTags('Catalog')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('api/connectors')
export class ConnectorsController {
  constructor(
    private readonly queryBus: QueryBus,
    private readonly commandBus: CommandBus,
  ) {}

  @Get()
  @ApiOperation({ summary: 'Get all available connectors' })
  @ApiResponse({
    status: 200,
    description: 'Return all active connectors',
    type: [ConnectorResponseDto],
  })
  async getConnectors() {
    const result: Connector[] = await this.queryBus.execute(
      new GetConnectorsQuery(),
    );
    return {
      success: true,
      data: result.map((c) => ConnectorResponseDto.fromDomain(c)),
    };
  }

  @Get(':connectorKey/credentials')
  @ApiOperation({ summary: 'List my credentials of a connector (no secrets)' })
  @ApiResponse({ status: 200, type: [CredentialResponseDto] })
  async listCredentials(
    @Param('connectorKey') connectorKey: string,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    const result: CredentialSummary[] = await this.queryBus.execute(
      new ListCredentialsQuery(connectorKey, user.id),
    );
    return {
      success: true,
      data: result.map((c) => CredentialResponseDto.fromSummary(c)),
    };
  }

  @Post(':connectorKey/credentials')
  @ApiOperation({
    summary: 'Save an API key for a connector (stored encrypted)',
  })
  @ApiResponse({ status: 201, type: CredentialResponseDto })
  async createCredential(
    @Param('connectorKey') connectorKey: string,
    @Body() body: CreateApiKeyCredentialDto,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    const result: CredentialSummary = await this.commandBus.execute(
      new CreateApiKeyCredentialCommand(
        connectorKey,
        user.id,
        body.name,
        body.api_key,
      ),
    );
    return { success: true, data: CredentialResponseDto.fromSummary(result) };
  }
}
import { ApiProperty } from '@nestjs/swagger';
import { IsNotEmpty, IsString, MaxLength } from 'class-validator';

export class CreateApiKeyCredentialDto {
  @ApiProperty({ example: 'OpenAI personal' })
  @IsString()
  @IsNotEmpty()
  @MaxLength(255)
  name: string;

  @ApiProperty({ description: 'Stored encrypted; never returned by the API' })
  @IsString()
  @IsNotEmpty()
  api_key: <REDACTED>;
}
// What the API may reveal about a stored credential: never the secret itself.
export interface CredentialSummary {
  id: string;
  connectorKey: string;
  name: string;
  createdAt: Date;
}
