import { placeholderFor, propertyTitle } from '../../utils/node-config';
import type { PropertySchema } from '../../utils/node-config';
import { CredentialPicker, OAuthField } from './CredentialField';
import { EnumField } from './EnumField';
import { NumberField } from './NumberField';
import { TextField } from './TextField';

interface ConfigFieldProps {
  fieldKey: string;
  schema: PropertySchema;
  config: Record<string, unknown>;
  onChange: (key: string, value: unknown) => void;
  onConnectOAuth: () => void;
}

// Picks the control for one config field from its JSON Schema and x-* hints.
export function ConfigField({
  fieldKey,
  schema,
  config,
  onChange,
  onConnectOAuth,
}: ConfigFieldProps) {
  const id = `field-${fieldKey}`;
  const label = propertyTitle(fieldKey, schema);
  const value = config[fieldKey];
  const change = (next: unknown) => onChange(fieldKey, next);

  if (typeof schema['x-connectorKeyFrom'] === 'string') {
    const provider = config[schema['x-connectorKeyFrom']];
    return (
      <CredentialPicker
        id={id}
        label={label}
        connectorKey={typeof provider === 'string' && provider ? provider : undefined}
        value={typeof value === 'string' ? value : ''}
        onChange={change}
      />
    );
  }
  if (schema['x-connectorKey']) {
    return (
      <OAuthField
        id={id}
        label={label}
        connectorName={String(schema['x-connectorKey'])}
        connected={!!value}
        onConnect={onConnectOAuth}
      />
    );
  }
  if (Array.isArray(schema.enum)) {
    return (
      <EnumField
        id={id}
        label={label}
        options={schema.enum.map(String)}
        value={typeof value === 'string' ? value : ''}
        onChange={change}
      />
    );
  }
  if (schema.type === 'integer' || schema.type === 'number') {
    return (
      <NumberField
        id={id}
        label={label}
        integer={schema.type === 'integer'}
        min={typeof schema.minimum === 'number' ? schema.minimum : undefined}
        value={typeof value === 'number' ? value : undefined}
        onChange={change}
      />
    );
  }
  return (
    <TextField
      id={id}
      label={label}
      multiline={schema['x-multiline'] === true}
      expression={schema['x-allowExpression'] === true}
      placeholder={placeholderFor(schema, config)}
      value={typeof value === 'string' ? value : ''}
      onChange={change}
    />
  );
}
    .map(([key]) => key);
}

// x-placeholderByField: { field, values } -> the hint for the current value of `field`.
export function placeholderFor(
  property: PropertySchema,
  config: Record<string, unknown>,
): string | undefined {
  const rule = property['x-placeholderByField'];
  if (typeof rule !== 'object' || rule === null) return undefined;
  const { field, values } = rule as { field?: unknown; values?: unknown };
  if (typeof field !== 'string' || typeof values !== 'object' || values === null) {
    return undefined;
  }
  const hint = (values as Record<string, unknown>)[String(config[field] ?? '')];
  return typeof hint === 'string' ? hint : undefined;
}

// Text typed into a number box: empty or not a number means "not set".
export function parseNumberInput(raw: string): number | undefined {
  if (raw.trim() === '') return undefined;
  const value = Number(raw);
  return Number.isFinite(value) ? value : undefined;
}

// Fields in display order. The database does not keep the order properties were
// written in (JSONB reorders keys), so a schema lists it in `x-propertyOrder`;
// fields it does not mention follow in their stored order.

