import { createHmac, timingSafeEqual } from 'node:crypto';

// Meta signs every webhook call: X-Hub-Signature-256 = "sha256=" + HMAC-SHA256
// of the exact request bytes, keyed with the app secret.
export function isValidMetaSignature(
  rawBody: Buffer | undefined,
  header: string | undefined,
  appSecret: <REDACTED> | undefined,
): boolean {
  if (!rawBody || !header || !appSecret) return false;
  const expected = Buffer.from(
    `sha256=${createHmac('sha256', appSecret).update(rawBody).digest('hex')}`,
  );
  const received = Buffer.from(header.trim());
  return (
    received.length === expected.length && timingSafeEqual(received, expected)
  );
}

export interface MessengerMessage {
  pageId: string;
  messageId: string;
  item: { json: Record<string, unknown> };
}

interface MessagingEvent {
  sender?: { id?: unknown };
  recipient?: { id?: unknown };
  timestamp?: unknown;
  message?: {
    mid?: unknown;
    text?: unknown;
    is_echo?: unknown;
    attachments?: Array<{ type?: unknown; payload?: { url?: unknown } }>;
  };
}

// One item per message a customer sent. Echoes (messages the Page itself sent,
// including the bot's replies), deliveries, reads and other events are dropped,
// so a reply can never start the workflow again.
export function parseMessengerMessages(body: unknown): MessengerMessage[] {
  const payload = body as { object?: unknown; entry?: unknown } | null;
  if (payload?.object !== 'page' || !Array.isArray(payload.entry)) return [];

  const messages: MessengerMessage[] = [];
  for (const entry of payload.entry as Array<{
    id?: unknown;
    messaging?: unknown;
  }>) {
    if (typeof entry?.id !== 'string' || !Array.isArray(entry.messaging)) {
      continue;
    }
    for (const event of entry.messaging as MessagingEvent[]) {
      const message = event?.message;
      const senderId = event?.sender?.id;
      if (
        !message ||
        message.is_echo === true ||
        typeof message.mid !== 'string' ||
        typeof senderId !== 'string'
      ) {
        continue;
      }
      messages.push({
        pageId: entry.id,
        messageId: message.mid,
        item: {
          json: {
            channel: 'messenger',
            message_id: message.mid,
            sender_id: senderId,
            recipient_id:
              typeof event.recipient?.id === 'string'
                ? event.recipient.id
                : entry.id,
            text: typeof message.text === 'string' ? message.text : '',
            attachments: (message.attachments ?? []).map((attachment) => ({
              type: typeof attachment?.type === 'string' ? attachment.type : null,
              url:
                typeof attachment?.payload?.url === 'string'
                  ? attachment.payload.url
                  : null,
            })),
            timestamp:
              typeof event.timestamp === 'number'
                ? new Date(event.timestamp).toISOString()
                : null,
            raw: event as Record<string, unknown>,
          },
        },
      });
    }
  }
  return messages;
}

import { randomBytes } from 'node:crypto';

export enum TriggerChannel {
  WEBHOOK = 'WEBHOOK',
  MESSENGER = 'MESSENGER',
  ZALO_OA = 'ZALO_OA',
}

export const TriggerKeys = {
  WEBHOOK: 'trigger.webhook',
  MESSENGER_MESSAGE: 'trigger.messenger.message',
} as const;

// Node keys that make a published version listen for outside events.
const CHANNEL_BY_KEY: Record<string, TriggerChannel> = {
  [TriggerKeys.WEBHOOK]: TriggerChannel.WEBHOOK,
  [TriggerKeys.MESSENGER_MESSAGE]: TriggerChannel.MESSENGER,
};

export interface WorkflowTrigger {
  id: string;
  workflowId: string;
  workflowVersionId: string;
  nodeId: string;
  triggerKey: string;
  channel: TriggerChannel;
  // WEBHOOK: secret token in the URL. MESSENGER: page id.
  routingKey: string;
  isActive: boolean;
  createdAt: Date;
}

export type NewWorkflowTrigger = Pick<
  WorkflowTrigger,
  'nodeId' | 'triggerKey' | 'channel' | 'routingKey'
>;

export interface TriggerNode {
  nodeId: string;
  triggerKey: string;
  channel: TriggerChannel;
  // config.credential_id of chat triggers (the Page to listen on).
  credentialId?: string;
}

// Trigger nodes of a definition that need a listener (manual triggers don't).
export function findTriggerNodes(definition: unknown): TriggerNode[] {
  const nodes = (definition as { nodes?: unknown } | null)?.nodes;
  if (!Array.isArray(nodes)) return [];

  const found: TriggerNode[] = [];
  for (const node of nodes as Array<{
    id?: unknown;
    data?: { key?: unknown; config?: { credential_id?: unknown } };
  }>) {
    const key = node?.data?.key;
    if (typeof node?.id !== 'string' || typeof key !== 'string') continue;
    const channel = CHANNEL_BY_KEY[key];
    if (!channel) continue;
    const credentialId = node.data?.config?.credential_id;
    found.push({
      nodeId: node.id,
      triggerKey: key,
      channel,
      ...(typeof credentialId === 'string' && credentialId
        ? { credentialId }
        : {}),
    });
  }
  return found;
}

// Plans the listeners for a newly published version. A webhook node keeps the
// token it had in earlier versions, so its URL survives re-publishing; chat
// triggers listen on the key resolved from their credential (`channelKeys`,
// by node id) and are left out when it could not be resolved.
export function planTriggers(
  triggerNodes: TriggerNode[],
  previous: readonly WorkflowTrigger[],
  channelKeys: ReadonlyMap<string, string> = new Map(),
  newToken: <REDACTED> => string = generateWebhookToken,
): NewWorkflowTrigger[] {
  const planned: NewWorkflowTrigger[] = [];
  for (const { nodeId, triggerKey, channel } of triggerNodes) {
    if (channel !== TriggerChannel.WEBHOOK) {
      const routingKey = channelKeys.get(nodeId);
      if (routingKey) planned.push({ nodeId, triggerKey, channel, routingKey });
      continue;
    }
    const earlier = previous
      .filter((t) => t.nodeId === nodeId && t.channel === channel)
      .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())[0];
    planned.push({
      nodeId,
      triggerKey,
      channel,
      routingKey: earlier?.routingKey ?? newToken(),
    });
  }
  return planned;
}

export function generateWebhookToken(): string {
  return randomBytes(32).toString('base64url');
}

import {
  NewWorkflowTrigger,
  TriggerChannel,
  WorkflowTrigger,
} from './workflow-trigger';

export interface StoredCredential {
  connectorKey: string;
  secret: <REDACTED>, unknown>;
}

export abstract class WorkflowTriggerRepository {
  abstract findActive(
    channel: TriggerChannel,
    routingKey: string,
  ): Promise<WorkflowTrigger | null>;
  // Every row of the workflow, active or not (to reuse webhook tokens).
  abstract findByWorkflow(workflowId: string): Promise<WorkflowTrigger[]>;
  // In one transaction: deactivate the workflow's listeners, add the new ones.
  abstract replaceActive(
    workflowId: string,
    workflowVersionId: string,
    triggers: NewWorkflowTrigger[],
  ): Promise<void>;
  abstract findWorkflowOwnerId(workflowId: string): Promise<string | null>;
  abstract findWorkflowName(workflowId: string): Promise<string | null>;
  // Decrypted credential if it exists and belongs to `ownerId`, else null.
  abstract findCredential(
    credentialId: string,
    ownerId: string,
  ): Promise<StoredCredential | null>;
}

