export interface MessengerSendRequest {
  pageAccessToken: <REDACTED>;
  recipientId: string; // page-scoped id of the customer (sender_id of the trigger)
  text: string;
}

export interface MessengerClient {
  sendText(request: MessengerSendRequest): Promise<{ messageId: string }>;
}

export class MessengerApiError extends Error {
  constructor(
    message: string,
    readonly retryable: boolean,
  ) {
    super(message);
  }
}

import axios, { AxiosError } from 'axios';
import { MessengerLimits } from '../../domain/constants/execution.constants';
import {
  MessengerApiError,
  MessengerClient,
  MessengerSendRequest,
} from '../../application/ports/messenger-client.port';

const DEFAULT_GRAPH_VERSION = 'v23.0';

interface GraphError {
  message?: string;
  code?: number;
  error_subcode?: number;
}

// Send API of the Facebook Graph API: POST /{version}/me/messages.
export class GraphMessengerClient implements MessengerClient {
  async sendText(
    request: MessengerSendRequest,
  ): Promise<{ messageId: string }> {
    const version = process.env['META_GRAPH_VERSION'] || DEFAULT_GRAPH_VERSION;
    try {
      const response = await axios.post<{ message_id?: string }>(
        `https://graph.facebook.com/${version}/me/messages`,
        {
          recipient: { id: request.recipientId },
          // A reply to a message the customer sent (allowed for 24 hours).
          messaging_type: 'RESPONSE',
          message: { text: request.text },
        },
        {
          params: { access_token: <REDACTED> },
          timeout: MessengerLimits.REQUEST_TIMEOUT_MS,
        },
      );
      return { messageId: response.data.message_id ?? '' };
    } catch (error) {
      throw toMessengerError(error);
    }
  }
}

// Rate limits, timeouts and 5xx are retryable; Graph explains everything else.
export function toMessengerError(error: unknown): MessengerApiError {
  if (!(error instanceof AxiosError)) {
    return new MessengerApiError(
      error instanceof Error ? error.message : 'Messenger request failed',
      false,
    );
  }
  if (!error.response) {
    // No answer: timeout or network problem.
    return new MessengerApiError(
      `Messenger did not answer (${error.code ?? 'network error'})`,
      true,
    );
  }

  const status = error.response.status;
  const graph = (error.response.data as { error?: GraphError } | undefined)
    ?.error;
  const code = graph?.code;
  if (code === 10 && graph?.error_subcode === 2018278) {
    return new MessengerApiError(
      'Messenger only allows replies within 24 hours of the customer’s last message',
      false,
    );
  }
  if (code === 551) {
    return new MessengerApiError(
      'This person is not available on Messenger right now',
      false,
    );
  }
  if (code === 190) {
    return new MessengerApiError(
      'The Page Access Token is invalid or expired; connect the Page again',
      false,
    );
  }
  const rateLimited = code === 4 || code === 32 || code === 613;
  return new MessengerApiError(
    `Messenger API error (${status}): ${graph?.message ?? error.message}`,
    status === 429 || status >= 500 || rateLimited,
  );
}

import { z } from 'zod';
import { IPerItemExecutor } from '../../domain/entities/node-executor';
import {
  ConnectorKeys,
  MessengerLimits,
  NodeKeys,
} from '../../domain/constants/execution.constants';
import { Item, ItemJson } from '../../domain/models/item';
import {
  MessengerApiError,
  MessengerClient,
} from '../ports/messenger-client.port';
import { GraphMessengerClient } from '../../infrastructure/messenger/graph-messenger.client';
import { Sleep } from './llm-generate-executor';

const ConfigSchema = z.object({
  credential_id: z.string().min(1),
  recipient_id: z
    .string()
    .trim()
    .min(1, 'Messenger config.recipient_id must resolve to a customer id'),
  text: z
    .string()
    .trim()
    .min(1, 'Messenger config.text must not be empty')
    .max(
      MessengerLimits.MAX_TEXT_LENGTH,
      `Messenger messages are limited to ${MessengerLimits.MAX_TEXT_LENGTH} characters`,
    ),
});

export type MessengerSendConfig = z.infer<typeof ConfigSchema>;

const CredentialSchema = z.object({
  page_id: z.string().min(1),
  page_access_token: <REDACTED>,
});

const defaultSleep: Sleep = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

// Sends one text message per item from the Page of the credential.
export class MessengerSendExecutor implements IPerItemExecutor<MessengerSendConfig> {
  readonly key = NodeKeys.MESSENGER_SEND;
  readonly runMode = 'per_item' as const;

  constructor(
    private readonly client: MessengerClient = new GraphMessengerClient(),
    private readonly sleep: Sleep = defaultSleep,
  ) {}

  parseConfig(raw: unknown): MessengerSendConfig {
    return ConfigSchema.parse(raw);
  }

  expectedConnectorKey(): string {
    return ConnectorKeys.MESSENGER;
  }

  async executeItem(params: {
    config: MessengerSendConfig;
    item: Item;
    credential: unknown;
  }): Promise<ItemJson> {
    const { page_access_token: <REDACTED> } = CredentialSchema.parse(
      params.credential,
    );
    const { recipient_id: recipientId, text } = params.config;

    const { messageId } = await this.sendWithRetry(() =>
      this.client.sendText({ pageAccessToken, recipientId, text }),
    );
    return { recipient_id: recipientId, message_id: messageId, status: 'sent' };
  }

  private async sendWithRetry<T>(attempt: () => Promise<T>): Promise<T> {
    for (let retry = 0; ; retry += 1) {
      try {
        return await attempt();
      } catch (error) {
        const retryable = error instanceof MessengerApiError && error.retryable;
        if (!retryable || retry >= MessengerLimits.MAX_RETRIES) throw error;
        await this.sleep(1000 * 2 ** retry);
      }
    }
  }
}

