import { apiClient } from '../../../shared/api/http-client';
import type {
  ConnectorSummary,
  CreateCredentialRequest,
  CredentialSummary,
} from '../types/credential.types';

export const credentialApi = {
  list: async (connectorKey: string): Promise<CredentialSummary[]> => {
    const res = await apiClient.get<{ data: CredentialSummary[] }>(
      `/api/connectors/${connectorKey}/credentials`,
    );
    return res.data.data;
  },

  create: async (
    connectorKey: string,
    body: CreateCredentialRequest,
  ): Promise<CredentialSummary> => {
    const res = await apiClient.post<{ data: CredentialSummary }>(
      `/api/connectors/${connectorKey}/credentials`,
      body,
    );
    return res.data.data;
  },

  listConnectors: async (): Promise<ConnectorSummary[]> => {
    const res = await apiClient.get<{ data: ConnectorSummary[] }>('/api/connectors');
    return res.data.data;
  },
};

import { credentialApi } from '../api/credential.api';
import { orderedProperties, propertyTitle } from '../utils/node-config';
import type {
  ConnectorSummary,
  CredentialFormField,
  CredentialSummary,
} from '../types/credential.types';

// Connectors whose schema declares no field take a single API key.
const API_KEY_FIELD: CredentialFormField = { key: 'api_key', title: 'API key', secret: <REDACTED> };

export const credentialService = {
  list: (connectorKey: string): Promise<CredentialSummary[]> =>
    credentialApi.list(connectorKey),

  listConnectors: (): Promise<ConnectorSummary[]> => credentialApi.listConnectors(),

  save: (
    connectorKey: string,
    name: string,
    values: Record<string, string>,
  ): Promise<CredentialSummary> =>
    credentialApi.create(connectorKey, {
      name: name.trim(),
      secret: <REDACTED>
        Object.entries(values).map(([key, value]) => [key, value.trim()]),
      ),
    }),

  // Inputs of the "add credential" form; x-secret fields are typed hidden.
  formFields: (connector: ConnectorSummary | undefined): CredentialFormField[] => {
    const fields = orderedProperties(connector?.configSchema).map(([key, property]) => ({
      key,
      title: propertyTitle(key, property),
      secret: <REDACTED>'x-secret'] === true,
    }));
    return fields.length > 0 ? fields : [API_KEY_FIELD];
  },
};

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { credentialService } from '../services/credential.service';
import type { ConnectorSummary, CredentialSummary } from '../types/credential.types';

export const credentialKeys = {
  all: ['credentials'] as const,
  list: (connectorKey: string) => [...credentialKeys.all, connectorKey] as const,
  connectors: ['connectors'] as const,
};

export function useCredentials(connectorKey: string | undefined) {
  return useQuery<CredentialSummary[]>({
    queryKey: credentialKeys.list(connectorKey ?? ''),
    queryFn: () => credentialService.list(connectorKey as string),
    enabled: !!connectorKey,
  });
}

// The catalog rarely changes: fetched once per session.
export function useConnector(connectorKey: string | undefined) {
  return useQuery<ConnectorSummary[], Error, ConnectorSummary | undefined>({
    queryKey: credentialKeys.connectors,
    queryFn: () => credentialService.listConnectors(),
    staleTime: Infinity,
    enabled: !!connectorKey,
    select: (connectors) => connectors.find((c) => c.key === connectorKey),
  });
}

interface SaveCredentialVariables {
  connectorKey: string;
  name: string;
  values: Record<string, string>;
}

export function useSaveCredential() {
  const queryClient = useQueryClient();
  return useMutation<CredentialSummary, Error, SaveCredentialVariables>({
    mutationFn: ({ connectorKey, name, values }) =>
      credentialService.save(connectorKey, name, values),
    onSuccess: (saved) => {
      void queryClient.invalidateQueries({
        queryKey: credentialKeys.list(saved.connectorKey),
      });
    },
  });
}

