// An outside application FlowPilot can be triggered by (and maybe reply to).
// Adding an app means adding one AppDefinition: the webhook ingress, the
// trigger routing, the Reply node and the designer only talk to this contract.

export interface AppEventSpec {
  key: string; // e.g. 'message'
  name: string; // e.g. 'New message'
  // The event carries text, so triggers can match keywords on it.
  hasText: boolean;
}

export interface IncomingAppRequest {
  method: 'GET' | 'POST';
  // Second path segment of /api/webhooks/:app/:token (token-routed apps).
  token?: string;
  query: Record<string, unknown>;
  headers: Record<string, string | string[] | undefined>;
  body: unknown;
  rawBody?: Buffer; // exact bytes, for signature checks
}

// Where a Reply goes: put into the trigger item as `conversation`.
export interface ConversationRef {
  app: string;
  recipient_id: string;
  // Added by the triggers module: the connection of the trigger that ran.
  credential_id?: string;
}

export interface AppEvent {
  // Which listener the event is for: the URL token, or e.g. a Page id.
  routingKey: string;
  eventType: string;
  // Same id within 24h is processed once.
  eventId?: string;
  text?: string;
  item: { json: Record<string, unknown> };
}

export interface AppConnection {
  connectorKey: string;
  // The designer offers a "Connect" sign-in button (else a typed-in form).
  oauth: boolean;
}

export interface AppDefinition {
  key: string;
  name: string;
  description: string;
  icon: string;
  events: AppEventSpec[];
  connection: AppConnection | null;
  // 'token': <REDACTED> generates a secret URL per trigger node.
  // 'connection': the routing key comes from the trigger's credential.
  routing: 'token' | 'connection';
  routingKeyFromSecret?(secret: <REDACTED>, unknown>): string | null;
  // HTTP status answered for an accepted call.
  ackStatus: number;
  // Setup check some apps make with a GET (returns the body to answer, or
  // null to refuse). Apps without it do not accept GET.
  handshake?(request: IncomingAppRequest): string | null;
  verify(request: IncomingAppRequest): boolean;
  parse(request: IncomingAppRequest): AppEvent[];
  reply?(
    secret: <REDACTED>, unknown>,
    recipientId: string,
    text: string,
  ): Promise<{ messageId: string }>;
}

// An app API refused or failed a call; `retryable` for rate limits and outages.
export class AppApiError extends Error {
  constructor(
    message: string,
    readonly retryable: boolean,
  ) {
    super(message);
  }
}

import { AppDefinition } from './app-definition';

export class AppRegistry {
  private readonly byKey: ReadonlyMap<string, AppDefinition>;

  constructor(apps: AppDefinition[]) {
    this.byKey = new Map(apps.map((app) => [app.key, app]));
  }

  all(): AppDefinition[] {
    return [...this.byKey.values()];
  }

  find(key: unknown): AppDefinition | undefined {
    return typeof key === 'string' ? this.byKey.get(key) : undefined;
  }
}

import { AppDefinition, IncomingAppRequest } from '../app-definition';

// Credentials of the caller must not end up in execution logs.
const HIDDEN_HEADERS = new Set([
  'authorization',
  'proxy-authorization',
  'cookie',
  'x-api-key',
]);

// Any system that can send an HTTP POST. The secret token in the URL is the
// only credential, so every call to a known token is accepted.
export const webhookApp: AppDefinition = {
  key: 'webhook',
  name: 'Webhook',
  description: 'Start when an HTTP POST arrives at the workflow’s own URL',
  icon: 'webhook',
  events: [{ key: 'request', name: 'Incoming request', hasText: false }],
  connection: null,
  routing: 'token',
  ackStatus: 202,

  verify: () => true,

  parse(request) {
    if (!request.token) return [];
    const idempotencyKey = headerValue(request, 'idempotency-key')?.trim();
    return [
      {
        routingKey: request.token,
        eventType: 'request',
        ...(idempotencyKey ? { eventId: idempotencyKey } : {}),
        item: { json: webhookJson(request, new Date()) },
      },
    ];
  },
};

export function webhookJson(
  request: IncomingAppRequest,
  receivedAt: Date,
): Record<string, unknown> {
  const headers: Record<string, string> = {};
  for (const [name, value] of Object.entries(request.headers)) {
    if (value === undefined || HIDDEN_HEADERS.has(name.toLowerCase())) continue;
    headers[name.toLowerCase()] = Array.isArray(value)
      ? value.join(', ')
      : value;
  }
  return {
    body: request.body ?? null,
    query: request.query,
    headers,
    received_at: receivedAt.toISOString(),
  };
}

function headerValue(
  request: IncomingAppRequest,
  name: string,
): string | undefined {
  const value = request.headers[name];
  return Array.isArray(value) ? value[0] : value;
}

