import axios, { AxiosError } from 'axios';
import { AppApiError } from '../app-definition';

const DEFAULT_GRAPH_VERSION = 'v23.0';
const REQUEST_TIMEOUT_MS = 15_000;

export interface FacebookPage {
  id: string;
  name: string;
  accessToken: <REDACTED>;
}

// The Facebook Graph API calls FlowPilot makes; replaced by a fake in tests.
export interface MetaGraphApi {
  sendText(
    pageAccessToken: <REDACTED>,
    recipientId: string,
    text: string,
  ): Promise<{ messageId: string }>;
  // OAuth "Connect Facebook Page": code → user token → long-lived token.
  exchangeCode(code: string, redirectUri: string): Promise<string>;
  exchangeLongLived(userToken: <REDACTED> Promise<string>;
  // Pages the user granted, each with a Page token (never expires when it
  // comes from a long-lived user token).
  listPages(userToken: <REDACTED> Promise<FacebookPage[]>;
  // Makes Meta send the Page's messages to the app's webhook.
  subscribePage(pageId: string, pageAccessToken: <REDACTED> Promise<void>;
}

export function graphVersion(): string {
  return process.env['META_GRAPH_VERSION'] || DEFAULT_GRAPH_VERSION;
}

export class HttpMetaGraphApi implements MetaGraphApi {
  private url(path: string) {
    return `https://graph.facebook.com/${graphVersion()}/${path}`;
  }

  async sendText(pageAccessToken: <REDACTED>, recipientId: string, text: string) {
    const data = await this.call<{ message_id?: string }>('post', 'me/messages', {
      params: { access_token: <REDACTED> },
      data: {
        recipient: { id: recipientId },
        // A reply to a message the customer sent (allowed for 24 hours).
        messaging_type: 'RESPONSE',
        message: { text },
      },
    });
    return { messageId: data.message_id ?? '' };
  }

  async exchangeCode(code: string, redirectUri: string) {
    const data = await this.call<{ access_token: <REDACTED> }>(
      'get',
      'oauth/access_token',
      {
        params: {
          ...appCredentials(),
          redirect_uri: redirectUri,
          code,
        },
      },
    );
    return data.access_token;
  }

  async exchangeLongLived(userToken: <REDACTED> {
    const data = await this.call<{ access_token: <REDACTED> }>(
      'get',
      'oauth/access_token',
      {
        params: {
          ...appCredentials(),
          grant_type: 'fb_exchange_token',
          fb_exchange_token: <REDACTED>,
        },
      },
    );
    return data.access_token;
  }

  async listPages(userToken: <REDACTED> {
    const data = await this.call<{
      data?: Array<{ id: string; name: string; access_token: <REDACTED> }>;
    }>('get', 'me/accounts', {
      params: {
        access_token: <REDACTED>,
        fields: 'id,name,access_token',
        limit: 100,
      },
    });
    return (data.data ?? []).map((page) => ({
      id: page.id,
      name: page.name,
      accessToken: <REDACTED>,
    }));
  }

  async subscribePage(pageId: string, pageAccessToken: <REDACTED> {
    await this.call('post', `${pageId}/subscribed_apps`, {
      params: {
        access_token: <REDACTED>,
        subscribed_fields: 'messages',
      },
    });
  }

  private async call<T>(
    method: 'get' | 'post',
    path: string,
    options: { params?: Record<string, unknown>; data?: unknown },
  ): Promise<T> {
    try {
      const response = await axios.request<T>({
        method,
        url: this.url(path),
        params: options.params,
        data: options.data,
        timeout: REQUEST_TIMEOUT_MS,
      });
      return response.data;
    } catch (error) {
      throw toAppApiError(error);
    }
  }
}

function appCredentials() {
  return {
    client_id: process.env['META_APP_ID'],
    client_secret: <REDACTED>'META_APP_SECRET'],
  };
}

interface GraphError {
  message?: string;
  code?: number;
  error_subcode?: number;
}

// Rate limits, timeouts and 5xx are retryable; Graph explains everything else.
export function toAppApiError(error: unknown): AppApiError {
  if (!(error instanceof AxiosError)) {
    return new AppApiError(
      error instanceof Error ? error.message : 'Facebook request failed',
      false,
    );
  }
  if (!error.response) {
    return new AppApiError(
      `Facebook did not answer (${error.code ?? 'network error'})`,
      true,
    );
  }

  const status = error.response.status;
  const graph = (error.response.data as { error?: GraphError } | undefined)
    ?.error;
  const code = graph?.code;
  if (code === 10 && graph?.error_subcode === 2018278) {
    return new AppApiError(
      'Messenger only allows replies within 24 hours of the customer’s last message',
      false,
    );
  }
  if (code === 551) {
    return new AppApiError(
      'This person is not available on Messenger right now',
      false,
    );
  }
  if (code === 190) {
    return new AppApiError(
      'The Facebook Page connection has expired; connect the Page again',
      false,
    );
  }
  const rateLimited = code === 4 || code === 32 || code === 613;
  return new AppApiError(
    `Facebook API error (${status}): ${graph?.message ?? error.message}`,
    status === 429 || status >= 500 || rateLimited,
  );
}

import { createHmac, timingSafeEqual } from 'node:crypto';
import {
  AppDefinition,
  AppEvent,
  IncomingAppRequest,
} from '../app-definition';
import { MetaGraphApi } from './meta-graph.api';

interface MessagingEvent {
  sender?: { id?: unknown };
  recipient?: { id?: unknown };
  timestamp?: unknown;
  message?: {
    mid?: unknown;
    text?: unknown;
    is_echo?: unknown;
    attachments?: Array<{ type?: unknown; payload?: { url?: unknown } }>;
  };
}

// Facebook Page messages. FlowPilot runs ONE Meta app for everybody: its
// secret, verify token and webhook URL are server settings (.env); a user
// only connects their Page.
export function createMessengerApp(graph: MetaGraphApi): AppDefinition {
  return {
    key: 'messenger',
    name: 'Facebook Messenger',
    description: 'Start when a customer messages your Facebook Page',
    icon: 'message-circle',
    events: [{ key: 'message', name: 'New message', hasText: true }],
    connection: { connectorKey: 'messenger', oauth: true },
    routing: 'connection',
    ackStatus: 200,

    routingKeyFromSecret(secret) {
      const pageId = secret.page_id;
      return typeof pageId === 'string' && pageId.trim() ? pageId.trim() : null;
    },

    // Meta calls this once when the webhook is set up in the app dashboard.
