import { Injectable } from '@nestjs/common';
import { WorkflowTrigger as WorkflowTriggerRow } from '@prisma/client';
import { PrismaService } from '@app/database';
import { EncryptionUtil } from '@app/shared/utils/encryption.util';
import {
  StoredCredential,
  WorkflowTriggerRepository,
} from '../domain/workflow-trigger.repository';
import {
  MatchMode,
  NewWorkflowTrigger,
  WorkflowTrigger,
} from '../domain/workflow-trigger';

const toDomain = (row: WorkflowTriggerRow): WorkflowTrigger => ({
  id: row.id,
  workflowId: row.workflowId,
  workflowVersionId: row.workflowVersionId,
  nodeId: row.nodeId,
  appKey: row.appKey,
  eventType: row.eventType,
  routingKey: row.routingKey,
  credentialId: row.credentialId,
  matchMode: row.matchMode as MatchMode,
  keywords: row.keywords,
  isActive: row.isActive,
  createdAt: row.createdAt,
});

@Injectable()
export class PrismaWorkflowTriggerRepository implements WorkflowTriggerRepository {
  constructor(private readonly prisma: PrismaService) {}

  async findActiveFor(
    appKey: string,
    routingKey: string,
    eventType: string,
  ): Promise<WorkflowTrigger[]> {
    const rows = await this.prisma.workflowTrigger.findMany({
      where: { appKey, routingKey, eventType, isActive: true },
      orderBy: { createdAt: 'asc' },
    });
    return rows.map(toDomain);
  }

  async findByWorkflow(workflowId: string): Promise<WorkflowTrigger[]> {
    const rows = await this.prisma.workflowTrigger.findMany({
      where: { workflowId },
      orderBy: { createdAt: 'desc' },
    });
    return rows.map(toDomain);
  }

  async replaceActive(
    workflowId: string,
    workflowVersionId: string,
    triggers: NewWorkflowTrigger[],
  ): Promise<void> {
    await this.prisma.$transaction([
      this.prisma.workflowTrigger.updateMany({
        where: { workflowId, isActive: true },
        data: { isActive: false },
      }),
      this.prisma.workflowTrigger.createMany({
        data: triggers.map((trigger) => ({
          ...trigger,
          workflowId,
          workflowVersionId,
        })),
      }),
    ]);
  }

  async findWorkflowOwnerId(workflowId: string): Promise<string | null> {
    const workflow = await this.prisma.workflow.findUnique({
      where: { id: workflowId },
      select: { ownerId: true },
    });
    return workflow?.ownerId ?? null;
  }

  async findWorkflowName(workflowId: string): Promise<string | null> {
    const workflow = await this.prisma.workflow.findUnique({
      where: { id: workflowId },
      select: { name: true },
    });
    return workflow?.name ?? null;
  }

  async findCredential(
    credentialId: string,
    ownerId: string,
  ): Promise<StoredCredential | null> {
    const credential = await this.prisma.connectorCredential.findUnique({
      where: { id: credentialId },
      include: { connector: { select: { key: true } } },
    });
    if (!credential || credential.ownerId !== ownerId) return null;

    const encryptionKey = process.env['ENCRYPTION_KEY'];
    if (!encryptionKey) {
      throw new Error('Credential decryption key is not configured');
    }
    const secret = <REDACTED>
      EncryptionUtil.decrypt(credential.encryptedSecret, encryptionKey),
    ) as Record<string, unknown>;
    return { connectorKey: credential.connector.key, secret };
  }
}

import { AppDefinition } from '@app/apps';
import { WorkflowTriggerRepository } from '../domain/workflow-trigger.repository';

const UUID_PATTERN =
  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

export type ConnectionRouting =
  | { routingKey: string }
  | { error: 'NOT_FOUND' | 'WRONG_APP' | 'NO_ROUTING_KEY' };

// The routing key a connection-routed app listens on (e.g. the Page id of a
// Messenger credential). The credential must belong to the workflow owner and
// to the app's connector.
export async function routingKeyOfConnection(
  repository: WorkflowTriggerRepository,
  app: AppDefinition,
  credentialId: string,
  ownerId: string,
): Promise<ConnectionRouting> {
  // The column is a UUID: anything else would make the query itself fail.
  if (!UUID_PATTERN.test(credentialId)) return { error: 'NOT_FOUND' };
  const credential = await repository.findCredential(credentialId, ownerId);
  if (!credential) return { error: 'NOT_FOUND' };
  if (credential.connectorKey !== app.connection?.connectorKey) {
    return { error: 'WRONG_APP' };
  }
  const routingKey = app.routingKeyFromSecret?.(credential.secret);
  return routingKey ? { routingKey } : { error: 'NO_ROUTING_KEY' };
}

