      status: number;
      started: string[]; // execution ids
      ignored: number; // duplicates, events nobody listens for
    };

import { Logger } from '@nestjs/common';
import { CommandBus, CommandHandler, ICommandHandler } from '@nestjs/cqrs';
import { AppRegistry } from '@app/apps';
import { EnqueueExecutionCommand } from '@app/execution/application/commands/enqueue-execution/enqueue-execution.command';
import { WorkflowTriggerRepository } from '../../domain/workflow-trigger.repository';
import { pickTrigger } from '../../domain/workflow-trigger';
import { WebhookDedupPort } from '../ports/webhook-dedup.port';

const DEDUP_TTL_SECONDS = 24 * 60 * 60;

// The one ingress for every app: verify, parse, route each event to a single
// listener, run it once, queue the run. No app-specific code here.
@CommandHandler(ReceiveAppEventsCommand)
export class ReceiveAppEventsHandler implements ICommandHandler<ReceiveAppEventsCommand> {
  private readonly logger = new Logger(ReceiveAppEventsHandler.name);

  constructor(
    private readonly apps: AppRegistry,
    private readonly repository: WorkflowTriggerRepository,
    private readonly dedup: WebhookDedupPort,
    private readonly commandBus: CommandBus,
  ) {}

  async execute(
    command: ReceiveAppEventsCommand,
  ): Promise<ReceiveAppEventsResult> {
    const app = this.apps.find(command.appKey);
    if (!app) return { outcome: 'unknown-app' };
    if (!app.verify(command.request)) return { outcome: 'rejected' };

    const started: string[] = [];
    let ignored = 0;
    let routed = 0;

    for (const event of app.parse(command.request)) {
      const trigger = pickTrigger(
        await this.repository.findActiveFor(
          app.key,
          event.routingKey,
          event.eventType,
        ),
        event.text,
      );
      if (!trigger) {
        this.logger.debug(
          `No ${app.key} listener for ${event.routingKey} / ${event.eventType}`,
        );
        ignored += 1;
        continue;
      }
      routed += 1;

      if (
        event.eventId &&
        !(await this.dedup.claim(
          `dedup:${app.key}:${event.routingKey}:${event.eventId}`,
          DEDUP_TTL_SECONDS,
        ))
      ) {
        ignored += 1;
        continue;
      }

      started.push(
        await this.commandBus.execute<EnqueueExecutionCommand, string>(
          new EnqueueExecutionCommand(trigger.workflowVersionId, [
            withConnection(event.item, trigger.credentialId),
          ]),
        ),
      );
    }

    // A wrong URL token is the caller's mistake, worth a 404.
    if (app.routing === 'token' && routed === 0) {
      return { outcome: 'not-found' };
    }
    return { outcome: 'accepted', status: app.ackStatus, started, ignored };
  }
}

// Reply needs to know which connection answers the conversation.
function withConnection(
  item: { json: Record<string, unknown> },
  credentialId: string | null,
): { json: Record<string, unknown> } {
  const conversation = item.json.conversation;
  if (!credentialId || typeof conversation !== 'object' || !conversation) {
    return item;
  }
  return {
    json: {
      ...item.json,
      conversation: { ...conversation, credential_id: credentialId },
    },
  };
}

import { Logger } from '@nestjs/common';
import { EventsHandler, IEventHandler } from '@nestjs/cqrs';
import { WorkflowPublishedEvent } from '@app/designer/application/events/workflow-published.event';
import { AppRegistry } from '@app/apps';
import { WorkflowTriggerRepository } from '../../domain/workflow-trigger.repository';
import {
  AppTriggerNode,
  findAppTriggerNodes,
  generateWebhookToken,
  NewWorkflowTrigger,
  WorkflowTrigger,
} from '../../domain/workflow-trigger';
import { routingKeyOfConnection } from '../connection-routing';

// Only the current version listens: re-publishing replaces the listeners.
@EventsHandler(WorkflowPublishedEvent)
export class SyncWorkflowTriggersHandler implements IEventHandler<WorkflowPublishedEvent> {
  private readonly logger = new Logger(SyncWorkflowTriggersHandler.name);

  constructor(
    private readonly apps: AppRegistry,
    private readonly repository: WorkflowTriggerRepository,
  ) {}

  async handle(event: WorkflowPublishedEvent): Promise<void> {
    try {
      const previous = await this.repository.findByWorkflow(event.workflowId);
      const ownerId = await this.repository.findWorkflowOwnerId(
        event.workflowId,
      );
      const triggers: NewWorkflowTrigger[] = [];
      for (const node of findAppTriggerNodes(event.definition)) {
        const planned = await this.plan(node, previous, ownerId);
        if (planned) triggers.push(planned);
      }
      await this.repository.replaceActive(
        event.workflowId,
        event.versionId,
        triggers,
      );
    } catch (error) {
      // The event bus swallows rejections; make the failure visible.
      this.logger.error(
        `Could not sync triggers of workflow ${event.workflowId}: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
    }
  }

  // Publish validation already rejected unusable nodes; anything that broke
  // since (e.g. a deleted credential) is skipped, as it cannot listen.
  private async plan(
    node: AppTriggerNode,
    previous: readonly WorkflowTrigger[],
    ownerId: string | null,
  ): Promise<NewWorkflowTrigger | null> {
    const app = this.apps.find(node.app);
    if (!app || typeof node.event !== 'string') return null;

    let routingKey: string;
    if (app.routing === 'token') {
      // Same node, same URL across versions.
      routingKey =
        previous.find((t) => t.nodeId === node.nodeId && t.appKey === app.key)
          ?.routingKey ?? generateWebhookToken();
    } else {
      if (!node.credentialId || !ownerId) return null;
      const routing = await routingKeyOfConnection(
        this.repository,
        app,
        node.credentialId,
        ownerId,
      );
      if ('error' in routing) {
        this.logger.warn(
          `App trigger ${node.nodeId} cannot listen (${routing.error})`,
        );
        return null;
      }
      routingKey = routing.routingKey;
    }

    return {
      nodeId: node.nodeId,
      appKey: app.key,
      eventType: node.event,
      routingKey,
      credentialId: node.credentialId ?? null,
      matchMode: node.matchMode,
      keywords: node.matchMode === 'any' ? [] : node.keywords,
    };
  }
}

