export interface TriggerAppView {
  key: string;
  name: string;
  description: string;
  icon: string;
  events: Array<{ key: string; name: string; hasText: boolean }>;
  connection: { connectorKey: string; oauth: boolean } | null;
  routing: 'token' | 'connection';
  canReply: boolean;
}

import { IQueryHandler, QueryHandler } from '@nestjs/cqrs';
import { AppRegistry } from '@app/apps';

// What the designer offers in the App Trigger node.
@QueryHandler(GetTriggerAppsQuery)
export class GetTriggerAppsHandler implements IQueryHandler<GetTriggerAppsQuery> {
  constructor(private readonly apps: AppRegistry) {}

  execute(): Promise<TriggerAppView[]> {
    return Promise.resolve(
      this.apps.all().map((app) => ({
        key: app.key,
        name: app.name,
        description: app.description,
        icon: app.icon,
        events: app.events.map(({ key, name, hasText }) => ({
          key,
          name,
          hasText,
        })),
        connection: app.connection,
        routing: app.routing,
        canReply: typeof app.reply === 'function',
      })),
    );
  }
}

