// One-time OAuth `state`: proves the callback answers a sign-in this server
// started, and for which user.
export abstract class OauthStateStore {
  abstract save(state: string, userId: string, ttlSeconds: number): Promise<void>;
  // The user of the state, removed at once so it cannot be replayed.
  abstract take(state: string): Promise<string | null>;
}

import { Injectable, OnModuleDestroy } from '@nestjs/common';
import Redis from 'ioredis';
import { OauthStateStore } from '../../application/ports/oauth-state.store';

@Injectable()
export class RedisOauthStateStore implements OauthStateStore, OnModuleDestroy {
  private readonly redis = new Redis({
    host: process.env['REDIS_HOST'] || 'localhost',
    port: parseInt(process.env['REDIS_PORT'] || '6379', 10),
    password: <REDACTED>'REDIS_PASSWORD'] || undefined,
    lazyConnect: true,
    maxRetriesPerRequest: 3,
  });

  async save(state: string, userId: string, ttlSeconds: number) {
    await this.redis.set(`oauth:state:${state}`, userId, 'EX', ttlSeconds);
  }

  async take(state: string) {
    return this.redis.getdel(`oauth:state:${state}`);
  }

  async onModuleDestroy(): Promise<void> {
    await this.redis.quit().catch(() => undefined);
  }
}

import { randomBytes } from 'node:crypto';
import { BadRequestException, Inject, Injectable } from '@nestjs/common';
import { META_GRAPH_API } from '@app/apps';
import type { MetaGraphApi } from '@app/apps/messenger/meta-graph.api';
import { graphVersion } from '@app/apps/messenger/meta-graph.api';
import { EncryptionUtil } from '@app/shared/utils/encryption.util';
import { ConnectorRepository } from '@app/connector/domain/repositories/connector.repository';
import { ConnectorCredentialRepository } from '@app/connector/domain/repositories/connector-credential.repository';
import { ConnectorCredential } from '@app/connector/domain/entities/connector-credential.entity';
import { OauthStateStore } from './ports/oauth-state.store';

const STATE_TTL_SECONDS = 600;
// Read the user's Pages, send messages as them, subscribe them to the app.
const SCOPES = ['pages_show_list', 'pages_messaging', 'pages_manage_metadata'];

export interface ConnectedPage {
  credentialId: string;
  pageId: string;
  name: string;
}

// "Connect Facebook Page": the user signs in to Facebook and picks Pages;
// FlowPilot stores one Messenger connection per Page and makes Meta send the
// Page's messages to the app's webhook. App id / secret are server settings.
@Injectable()
export class MetaOauthService {
  constructor(
    @Inject(META_GRAPH_API) private readonly graph: MetaGraphApi,
    private readonly states: OauthStateStore,
    private readonly connectors: ConnectorRepository,
    private readonly credentials: ConnectorCredentialRepository,
  ) {}

  async authUrl(userId: string): Promise<string> {
    const { appId, redirectUri } = settings();
    const state = randomBytes(24).toString('base64url');
    await this.states.save(state, userId, STATE_TTL_SECONDS);
    const query = new URLSearchParams({
      client_id: appId,
      redirect_uri: redirectUri,
      state,
      response_type: 'code',
      scope: SCOPES.join(','),
    });
    return `https://www.facebook.com/${graphVersion()}/dialog/oauth?${query.toString()}`;
  }

  async connect(code: string, state: string): Promise<ConnectedPage[]> {
    const userId = await this.states.take(state);
    if (!userId) {
      throw new BadRequestException(
        'This sign-in link has expired. Close the window and try again.',
      );
    }
    const { redirectUri } = settings();
    const shortToken = <REDACTED> this.graph.exchangeCode(code, redirectUri);
    const userToken = <REDACTED> this.graph.exchangeLongLived(shortToken);
    const pages = await this.graph.listPages(userToken);
    if (pages.length === 0) {
      throw new BadRequestException(
        'No Facebook Page was shared. Sign in again and select at least one Page.',
      );
    }

    const connector = await this.connectors.findByKey('messenger');
    if (!connector) {
      throw new BadRequestException('The Messenger connector is not set up');
    }
    const encryptionKey = process.env['ENCRYPTION_KEY'];
    if (!encryptionKey) throw new Error('ENCRYPTION_KEY is not defined');

    const existing = await this.credentials.findByOwnerAndConnector(
      userId,
      connector.id,
    );
    const connected: ConnectedPage[] = [];
    for (const page of pages) {
      await this.graph.subscribePage(page.id, page.accessToken);
      const encryptedSecret = <REDACTED>
        JSON.stringify({
          page_id: page.id,
          page_access_token: <REDACTED>,
          page_name: page.name,
        }),
        encryptionKey,
      );
      // Connecting a Page again refreshes its token instead of adding a copy.
      const previous = existing.find(
        (credential) => pageIdOf(credential, encryptionKey) === page.id,
      );
      let credentialId: string;
      if (previous?.id) {
        await this.credentials.save(
          new ConnectorCredential(
            previous.id,
            connector.id,
            userId,
            page.name,
            encryptedSecret,
            previous.lastTestedAt,
            previous.lastTestStatus,
            previous.createdAt,
          ),
        );
        credentialId = previous.id;
      } else {
        const saved = await this.credentials.create(
          new ConnectorCredential(
            undefined,
            connector.id,
            userId,
            page.name,
            encryptedSecret,
          ),
        );
        credentialId = saved.id!;
      }
      connected.push({ credentialId, pageId: page.id, name: page.name });
    }
    return connected;
  }
}

function settings() {
  const appId = process.env['META_APP_ID'];
  const redirectUri = process.env['META_REDIRECT_URI'];
  if (!appId || !redirectUri || !process.env['META_APP_SECRET']) {
    throw new BadRequestException(
