    credentialId: string,
    ownerId: string,
  ): Promise<ResolvedCredential> {
    if (ownerId === 'actor-1' && credentialId === PAGE_CREDENTIAL_ID) {
      return Promise.resolve({
        connectorKey: 'messenger',
        secret: <REDACTED> page_id: 'page-1', page_access_token: <REDACTED> },
      });
    }
    return super.resolveCredential(credentialId, ownerId);
  }
}

class CatalogWithReply extends FakeCatalog {
  async getConfigSchemas() {
    const schemas = await super.getConfigSchemas();
    schemas.set(NodeKeys.CHAT_REPLY, CHAT_REPLY_CONFIG_SCHEMA);
    return schemas;
  }
}

const trigger = {
  id: 'chat',
  data: {
    key: NodeKeys.TRIGGER_APP,
    name: 'Messenger',
    config: {
      app: 'messenger',
      event: 'message',
      credential_id: PAGE_CREDENTIAL_ID,
    },
  },
};
const reply = (text: string) => ({
  id: 'reply',
  data: { key: NodeKeys.CHAT_REPLY, name: 'Reply', config: { text } },
});
const customerMessage = (credentialId = PAGE_CREDENTIAL_ID) => ({
  json: {
    app: 'messenger',
    sender_id: 'customer-1',
    text: 'Shop ơi còn size M không?',
    conversation: {
      app: 'messenger',
      recipient_id: 'customer-1',
      credential_id: credentialId,
    },
  },
});

async function run(
  definition: unknown,
  options: {
    item?: { json: Record<string, unknown> };
    graph?: FakeMetaGraph;
  } = {},
) {
  const graph = options.graph ?? new FakeMetaGraph();
  const repository = new ChatRepository({
    id: 'version-1',
    workflowId: 'workflow-1',
    workflowOwnerId: 'actor-1',
    definition,
  });
  const llm = new FakeLlmProvider([llmText('Dạ còn ạ!')]);
  const engine = new WorkflowEngine(
    repository,
    [
      new PassThroughTriggerExecutor(NodeKeys.TRIGGER_APP),
      new LlmGenerateExecutor(new LlmProviderRegistry([llm]), 100, () =>
        Promise.resolve(),
      ),
      new AggregateExecutor(),
      new ReplyExecutor(
        new AppRegistry([webhookApp, createMessengerApp(graph)]),
        () => Promise.resolve(),
      ),
    ],
    new CatalogWithReply(),
  );
  const status = await engine.run(
    'execution-1',
    {
      id: 'version-1',
      workflowId: 'workflow-1',
      workflowOwnerId: 'actor-1',
      definition,
    },
    [options.item ?? customerMessage()],
    new Date(),
  );
  const replyLog = logOf(repository.logs, NodeKeys.CHAT_REPLY);
  return { status, graph, replyLog, llm };
}

describe('Reply node', () => {
  it('answers the customer with the LLM text, through the trigger Page', async () => {
    const { status, graph, llm, replyLog } = await run(
      chain([
        trigger,
        llmNode({ prompt: 'Trả lời khách: {{$json.text}}' }),
        reply('{{$json.text}}'),
      ]),
    );

    expect(status).toBe(ExecutionStatus.SUCCESS);
    expect(llm.requests[0].prompt).toBe(
      'Trả lời khách: Shop ơi còn size M không?',
    );
    expect(graph.sent).toEqual([
      { pageAccessToken: <REDACTED>, recipientId: 'customer-1', text: 'Dạ còn ạ!' },
    ]);
    expect((replyLog?.output as Array<{ json: unknown }>)[0].json).toEqual({
      app: 'messenger',
      recipient_id: 'customer-1',
      message_id: 'mid.1',
      status: 'sent',
    });
  });

  it('works right after the trigger', async () => {
    const { status, graph } = await run(
      chain([trigger, reply('Cảm ơn: {{$json.text}}')]),
    );
    expect(status).toBe(ExecutionStatus.SUCCESS);
    expect(graph.sent[0].text).toBe('Cảm ơn: Shop ơi còn size M không?');
  });

  it('still finds the conversation after Aggregate drops the item link', async () => {
    const { status, graph } = await run(
      chain([trigger, aggregateNode, reply('Đã nhận')]),
    );
    expect(status).toBe(ExecutionStatus.SUCCESS);
    expect(graph.sent[0].recipientId).toBe('customer-1');
  });

  it('fails clearly when the trigger did not receive a message', async () => {
    const { status, graph, replyLog } = await run(
      chain([
        {
          ...trigger,
          data: { ...trigger.data, config: { app: 'webhook', event: 'request' } },
        },
        reply('Hi'),
      ]),
      { item: { json: { body: {} } } },
    );
    expect(status).toBe(ExecutionStatus.FAILED);
    expect(replyLog?.errorMessage).toContain('Reply needs an App Trigger');
    expect(graph.sent).toEqual([]);
  });

  it('refuses a conversation whose connection belongs to another app', async () => {
    const { status, replyLog } = await run(chain([trigger, reply('Hi')]), {
      item: customerMessage('33333333-3333-3333-3333-333333333332'),
    });
    expect(status).toBe(ExecutionStatus.FAILED);
    expect(replyLog?.errorMessage).toContain('"messenger" connector');
  });

  it('rejects text longer than the app allows', async () => {
    const { status, replyLog } = await run(
      chain([trigger, reply('a'.repeat(2001))]),
    );
    expect(status).toBe(ExecutionStatus.FAILED);
    expect(replyLog?.errorMessage).toContain('2000 characters');
  });

  it('retries a rate-limited reply, but not a closed 24-hour window', async () => {
    const busy = new FakeMetaGraph([new AppApiError('busy', true)]);
    const retried = await run(chain([trigger, reply('Hi')]), { graph: busy });
    expect(retried.status).toBe(ExecutionStatus.SUCCESS);
    expect(busy.sent).toHaveLength(2);

    const closed = new FakeMetaGraph([new AppApiError('24 hours', false)]);
    const failed = await run(chain([trigger, reply('Hi')]), { graph: closed });
    expect(failed.status).toBe(ExecutionStatus.FAILED);
    expect(closed.sent).toHaveLength(1);
  });
});

// Facebook Graph API stand-in: records what would be sent, answers from a queue.
import type {
  FacebookPage,
  MetaGraphApi,
} from '@app/apps/messenger/meta-graph.api';

export interface SentMessage {
  pageAccessToken: <REDACTED>;
  recipientId: string;
  text: string;
}

export class FakeMetaGraph implements MetaGraphApi {
  sent: SentMessage[] = [];
  subscribed: Array<{ pageId: string; pageAccessToken: <REDACTED> }> = [];
  exchanged: Array<{ code: string; redirectUri: string }> = [];
  pages: FacebookPage[] = [
    { id: 'page-1', name: 'Shop ABC', accessToken: <REDACTED> },
  ];

  // Errors to throw from the next sendText calls, in order.
  constructor(private readonly sendFailures: Error[] = []) {}

  sendText(pageAccessToken: <REDACTED>, recipientId: string, text: string) {
    this.sent.push({ pageAccessToken, recipientId, text });
    const failure = this.sendFailures.shift();
    return failure
      ? Promise.reject(failure)
      : Promise.resolve({ messageId: `mid.${this.sent.length}` });
  }

  exchangeCode(code: string, redirectUri: string) {
    this.exchanged.push({ code, redirectUri });
    return Promise.resolve(`short-token-for-${code}`);
  }

  exchangeLongLived(userToken: <REDACTED> {
    return Promise.resolve(`long-${userToken}`);
  }

  listPages() {
    return Promise.resolve(this.pages);
  }

  subscribePage(pageId: string, pageAccessToken: <REDACTED> {
    this.subscribed.push({ pageId, pageAccessToken });
    return Promise.resolve();
  }
}

