import { createHmac } from 'node:crypto';
import { ForbiddenException, NotFoundException } from '@nestjs/common';
import { CommandBus } from '@nestjs/cqrs';
import {
  findAppTriggerNodes,
  normalizeText,
  parseKeywords,
  pickTrigger,
  sharedCondition,
  WorkflowTrigger,
} from '@app/triggers/domain/workflow-trigger';
import { SyncWorkflowTriggersHandler } from '@app/triggers/application/events/sync-workflow-triggers.handler';
import { CheckPublishTriggersHandler } from '@app/triggers/application/queries/check-publish-triggers.handler';
import {
  ReceiveAppEventsCommand,
  ReceiveAppEventsHandler,
} from '@app/triggers/application/commands/receive-app-events.command';
import {
  GetWorkflowTriggersHandler,
  GetWorkflowTriggersQuery,
} from '@app/triggers/application/queries/get-workflow-triggers.query';
import { GetTriggerAppsHandler } from '@app/triggers/application/queries/get-trigger-apps.query';
import { CheckPublishTriggersQuery } from '@app/designer/application/queries/check-publish-triggers.query';
import { WorkflowPublishedEvent } from '@app/designer/application/events/workflow-published.event';
import { EnqueueExecutionCommand } from '@app/execution/application/commands/enqueue-execution/enqueue-execution.command';
import { IncomingAppRequest } from '@app/apps';
import {
  LLM_CREDENTIAL_ID,
  MemoryDedup,
  MemoryTriggerRepository,
  MISSING_CREDENTIAL_ID,
  OTHER_PAGE_CREDENTIAL_ID,
  PAGE_CREDENTIAL_ID,
  testApps,
} from '@test/support/triggers/memory-triggers';

const appTrigger = (config: Record<string, unknown>, id = 'trigger') => ({
  id,
  data: { key: 'trigger.app', config },
});
const messengerTrigger = (config: Record<string, unknown> = {}) =>
  appTrigger({
    app: 'messenger',
    event: 'message',
    credential_id: PAGE_CREDENTIAL_ID,
    ...config,
  });
const webhookTrigger = (id = 'hook') =>
  appTrigger({ app: 'webhook', event: 'request' }, id);
const definition = (...nodes: unknown[]) => ({ nodes, edges: [] });

const listener = (overrides: Partial<WorkflowTrigger>): WorkflowTrigger => ({
  id: 'l',
  workflowId: 'wf',
  workflowVersionId: 'v',
  nodeId: 'n',
  appKey: 'messenger',
  eventType: 'message',
  routingKey: 'page-1',
  credentialId: PAGE_CREDENTIAL_ID,
  matchMode: 'any',
  keywords: [],
  isActive: true,
  createdAt: new Date(Date.UTC(2026, 0, 1)),
  ...overrides,
});

describe('keyword matching', () => {
  it('ignores case, Vietnamese accents and extra spaces', () => {
    expect(normalizeText('  Bảng   GIÁ Đẹp ')).toBe('bang gia dep');
    expect(parseKeywords('giá, Bảng giá , ,GIA')).toEqual(['gia', 'bang gia']);
    expect(parseKeywords(['Giá', 1])).toEqual(['gia']);
    expect(parseKeywords(undefined)).toEqual([]);
  });

  it('prefers an exact keyword, then a contained keyword, then every message', () => {
    const fallback = listener({ id: 'any' });
    const contains = listener({ id: 'kw', matchMode: 'keyword', keywords: ['gia'] });
    const exact = listener({ id: 'ex', matchMode: 'exact', keywords: ['gia'] });
    const all = [fallback, contains, exact];

    expect(pickTrigger(all, 'Giá')?.id).toBe('ex');
    expect(pickTrigger(all, 'cho xin bảng giá')?.id).toBe('kw');
    expect(pickTrigger(all, 'xin chào')?.id).toBe('any');
    expect(pickTrigger([contains], 'xin chào')).toBeUndefined();
  });

  it('breaks ties by the oldest listener', () => {
    const older = listener({ id: 'old', createdAt: new Date(1) });
    const newer = listener({ id: 'new', createdAt: new Date(2) });
    expect(pickTrigger([newer, older], 'x')?.id).toBe('old');
  });

  it('detects listeners an event could not tell apart', () => {
    const any = { matchMode: 'any' as const, keywords: [] };
    expect(sharedCondition(any, any)).toBe('every message');
    expect(
      sharedCondition(
        { matchMode: 'keyword', keywords: ['gia', 'ship'] },
        { matchMode: 'keyword', keywords: ['ship'] },
      ),
    ).toBe('the keyword "ship"');
    expect(
      sharedCondition(
        { matchMode: 'keyword', keywords: ['gia'] },
        { matchMode: 'exact', keywords: ['gia'] },
      ),
    ).toBeNull();
    expect(sharedCondition(any, { matchMode: 'keyword', keywords: ['x'] })).toBeNull();
  });

  it('reads App Trigger nodes from a definition', () => {
    expect(
      findAppTriggerNodes(
        definition(
          { id: 'm', data: { key: 'trigger.manual' } },
          messengerTrigger({ match_mode: 'keyword', keywords: 'Giá, ship' }),
        ),
      ),
    ).toEqual([
      {
        nodeId: 'trigger',
        app: 'messenger',
        event: 'message',
        credentialId: PAGE_CREDENTIAL_ID,
        matchMode: 'keyword',
        rawMatchMode: 'keyword',
        keywords: ['gia', 'ship'],
      },
    ]);
    expect(findAppTriggerNodes(null)).toEqual([]);
  });
});

describe('SyncWorkflowTriggersHandler', () => {
  const sync = (repository: MemoryTriggerRepository, version: string, ...nodes: unknown[]) =>
    new SyncWorkflowTriggersHandler(testApps(), repository).handle(
      new WorkflowPublishedEvent('wf', version, definition(...nodes)),
    );

  it('keeps the webhook token of a node across publishes, so its URL does not change', async () => {
    const repository = new MemoryTriggerRepository();
    await sync(repository, 'v1', webhookTrigger());
    const token = <REDACTED>;
    expect(token).toMatch(/^[A-Za-z0-9_-]{43}$/);

    await sync(repository, 'v2', webhookTrigger());
    const active = repository.rows.filter((r) => r.isActive);
    expect(active).toEqual([
      expect.objectContaining({ workflowVersionId: 'v2', routingKey: token }),
    ]);
  });

  it('listens on the Page of the connection with the node condition', async () => {
    const repository = new MemoryTriggerRepository();
    await sync(
      repository,
      'v1',
      messengerTrigger({ match_mode: 'keyword', keywords: 'Giá' }),
    );
    expect(repository.rows).toEqual([
      expect.objectContaining({
        appKey: 'messenger',
        eventType: 'message',
        routingKey: 'page-1',
        credentialId: PAGE_CREDENTIAL_ID,
        matchMode: 'keyword',
        keywords: ['gia'],
      }),
    ]);
  });

  it('stops listening when the trigger is gone, and skips broken nodes', async () => {
    const repository = new MemoryTriggerRepository();
    await sync(repository, 'v1', messengerTrigger());
    await sync(
      repository,
      'v2',
      { id: 'm', data: { key: 'trigger.manual' } },
      messengerTrigger({ credential_id: MISSING_CREDENTIAL_ID }),
      appTrigger({ app: 'nope', event: 'x' }),
    );
    expect(repository.rows.some((r) => r.isActive)).toBe(false);
  });

  it('does not throw when storing fails (the publish already succeeded)', async () => {
    const repository = new MemoryTriggerRepository();
    jest.spyOn(repository, 'replaceActive').mockRejectedValue(new Error('db down'));
    await expect(sync(repository, 'v1', webhookTrigger())).resolves.toBeUndefined();
  });
});

describe('CheckPublishTriggersHandler', () => {
  const check = (repository: MemoryTriggerRepository, ...nodes: unknown[]) =>
    new CheckPublishTriggersHandler(testApps(), repository).execute(
      new CheckPublishTriggersQuery('wf', 'owner-1', definition(...nodes)),
    );
  const codes = async (repository: MemoryTriggerRepository, node: unknown) =>
    (await check(repository, node)).map((issue) => [issue.code, issue.field]);

  it('passes webhook triggers and a free Page', async () => {
    const repository = new MemoryTriggerRepository();
    await expect(check(repository, webhookTrigger(), messengerTrigger())).resolves.toEqual(
      [],
    );
  });

  it('reports unknown apps and events, missing or wrong connections, missing keywords', async () => {
    const repository = new MemoryTriggerRepository();
    expect(await codes(repository, appTrigger({ app: 'telegram', event: 'x' }))).toEqual([
      ['UNKNOWN_APP', undefined],
    ]);
    expect(await codes(repository, appTrigger({ app: 'messenger', event: 'x' }))).toEqual([
      ['UNKNOWN_EVENT', undefined],
    ]);
    expect(await codes(repository, messengerTrigger({ credential_id: undefined }))).toEqual([
      ['MISSING_CONNECTION', 'credential_id'],
    ]);
    for (const credential of [MISSING_CREDENTIAL_ID, LLM_CREDENTIAL_ID, 'not-a-uuid']) {
      expect(
        await codes(repository, messengerTrigger({ credential_id: credential })),
      ).toEqual([['INVALID_CREDENTIAL', 'credential_id']]);
    }
    expect(
      await codes(repository, messengerTrigger({ match_mode: 'keyword', keywords: ' , ' })),
    ).toEqual([['MISSING_KEYWORDS', 'keywords']]);
    expect(
      await codes(repository, appTrigger({ app: 'webhook', event: 'request', match_mode: 'keyword', keywords: 'x' })),
    ).toEqual([['INVALID_TRIGGER_CONFIG', 'match_mode']]);
    expect(await codes(repository, messengerTrigger({ match_mode: 'sometimes' }))).toEqual([
      ['INVALID_TRIGGER_CONFIG', 'match_mode'],
    ]);
    // Missing app / event are reported as required fields elsewhere.
    expect(await codes(repository, appTrigger({}))).toEqual([]);
  });

  it('blocks a second "every message" workflow on a Page, naming the first one', async () => {
    const repository = new MemoryTriggerRepository();
    await repository.listen('wf-other', { routingKey: 'page-1' });

    const [issue] = await check(repository, messengerTrigger());
    expect(issue).toMatchObject({ code: 'TRIGGER_CONFLICT', nodeId: 'trigger' });
    expect(issue.message).toContain('"Other workflow"');
    expect(issue.message).toContain('every message');
  });

  it('allows keyword workflows next to the default one, but not the same keyword twice', async () => {
    const repository = new MemoryTriggerRepository();
    await repository.listen('wf-other', {
      routingKey: 'page-1',
      matchMode: 'keyword',
      keywords: ['gia'],
    });

    await expect(check(repository, messengerTrigger())).resolves.toEqual([]);
    await expect(
      check(repository, messengerTrigger({ match_mode: 'keyword', keywords: 'ship' })),
    ).resolves.toEqual([]);
    const [issue] = await check(
      repository,
      messengerTrigger({ match_mode: 'keyword', keywords: 'Giá, ship' }),
    );
    expect(issue.message).toContain('the keyword "gia"');
  });

  it('ignores its own listeners and other Pages', async () => {
    const repository = new MemoryTriggerRepository();
    await repository.listen('wf', { routingKey: 'page-1' });
    await repository.listen('wf-other', { routingKey: 'page-2' });
    await expect(check(repository, messengerTrigger())).resolves.toEqual([]);
    await expect(
      check(repository, messengerTrigger({ credential_id: OTHER_PAGE_CREDENTIAL_ID })),
    ).resolves.toEqual([expect.objectContaining({ code: 'TRIGGER_CONFLICT' })]);
  });
});

describe('ReceiveAppEventsHandler', () => {
  const previousEnv = { ...process.env };
  beforeEach(() => {
    process.env['META_APP_SECRET'] = 'app-secret';
  });
  afterAll(() => {
    process.env = previousEnv;
  });

  async function setup() {
    const repository = new MemoryTriggerRepository();
    await repository.listen('wf-default', { routingKey: 'page-1' });
    await repository.listen('wf-price', {
      routingKey: 'page-1',
      matchMode: 'keyword',
      keywords: ['gia'],
      credentialId: OTHER_PAGE_CREDENTIAL_ID,
    });
    await repository.listen('wf-hook', {
      appKey: 'webhook',
      eventType: 'request',
      routingKey: 'token-1',
      credentialId: null,
    });
    let next = 0;
    const commandBus = {
      execute: jest.fn(() => Promise.resolve(`execution-${(next += 1)}`)),
    };
    const handler = new ReceiveAppEventsHandler(
      testApps(),
      repository,
      new MemoryDedup(),
      commandBus as unknown as CommandBus,
    );
    const enqueued = () =>
      (commandBus.execute.mock.calls as unknown as Array<[EnqueueExecutionCommand]>).map(
        ([command]) => command,
      );
    return { handler, commandBus, enqueued };
  }

  const messengerCall = (...messaging: unknown[]): IncomingAppRequest => {
    const body = { object: 'page', entry: [{ id: 'page-1', messaging }] };
    const raw = Buffer.from(JSON.stringify(body));
    return {
      method: 'POST',
      query: {},
      body,
      rawBody: raw,
      headers: {
        'x-hub-signature-256': `sha256=${createHmac('sha256', 'app-secret').update(raw).digest('hex')}`,
      },
    };
  };
  const message = (mid: string, text: string) => ({
    sender: { id: 'customer-1' },
    message: { mid, text },
  });

  it('runs the keyword workflow for matching messages and the default one otherwise', async () => {
    const { handler, enqueued } = await setup();

    const result = await handler.execute(
      new ReceiveAppEventsCommand(
        'messenger',
        messengerCall(message('m_1', 'Cho xin bảng GIÁ'), message('m_2', 'xin chào')),
      ),
    );

    expect(result).toEqual({
      outcome: 'accepted',
      status: 200,
      started: ['execution-1', 'execution-2'],
      ignored: 0,
    });
    const [price, fallback] = enqueued();
    expect(price.workflowVersionId).toBe('wf-price-v');
    expect(fallback.workflowVersionId).toBe('wf-default-v');
    // Reply answers with the connection of the trigger that ran.
    expect(price.triggerItems[0].json.conversation).toEqual({
      app: 'messenger',
      recipient_id: 'customer-1',
      credential_id: OTHER_PAGE_CREDENTIAL_ID,
    });
  });

  it('runs a message once when the app delivers it again', async () => {
    const { handler, commandBus } = await setup();
    const call = messengerCall(message('m_1', 'hi'));
    await handler.execute(new ReceiveAppEventsCommand('messenger', call));
    const retry = await handler.execute(new ReceiveAppEventsCommand('messenger', call));
    expect(retry).toMatchObject({ started: [], ignored: 1 });
    expect(commandBus.execute).toHaveBeenCalledTimes(1);
  });

  it('rejects unsigned calls and unknown apps without running anything', async () => {
    const { handler, commandBus } = await setup();
    const unsigned = { ...messengerCall(message('m_1', 'hi')), headers: {} };
    await expect(
      handler.execute(new ReceiveAppEventsCommand('messenger', unsigned)),
    ).resolves.toEqual({ outcome: 'rejected' });
    await expect(
      handler.execute(new ReceiveAppEventsCommand('telegram', unsigned)),
    ).resolves.toEqual({ outcome: 'unknown-app' });
    expect(commandBus.execute).not.toHaveBeenCalled();
  });

  it('answers 202 for a known webhook token and not-found for an unknown one', async () => {
