  MISSING_CREDENTIAL_ID,
  OTHER_PAGE_CREDENTIAL_ID,
  PAGE_CREDENTIAL_ID,
  testApps,
} from '@test/support/triggers/memory-triggers';

const appTrigger = (config: Record<string, unknown>, id = 'trigger') => ({
  id,
  data: { key: 'trigger.app', config },
});
const messengerTrigger = (config: Record<string, unknown> = {}) =>
  appTrigger({
    app: 'messenger',
    event: 'message',
    credential_id: PAGE_CREDENTIAL_ID,
    ...config,
  });
const webhookTrigger = (id = 'hook') =>
  appTrigger({ app: 'webhook', event: 'request' }, id);
const definition = (...nodes: unknown[]) => ({ nodes, edges: [] });

const listener = (overrides: Partial<WorkflowTrigger>): WorkflowTrigger => ({
  id: 'l',
  workflowId: 'wf',
  workflowVersionId: 'v',
  nodeId: 'n',
  appKey: 'messenger',
  eventType: 'message',
  routingKey: 'page-1',
  credentialId: PAGE_CREDENTIAL_ID,
  matchMode: 'any',
  keywords: [],
  isActive: true,
  createdAt: new Date(Date.UTC(2026, 0, 1)),
  ...overrides,
});

describe('keyword matching', () => {
  it('ignores case, Vietnamese accents and extra spaces', () => {
    expect(normalizeText('  Bảng   GIÁ Đẹp ')).toBe('bang gia dep');
    expect(parseKeywords('giá, Bảng giá , ,GIA')).toEqual(['gia', 'bang gia']);
    expect(parseKeywords(['Giá', 1])).toEqual(['gia']);
    expect(parseKeywords(undefined)).toEqual([]);
  });

  it('prefers an exact keyword, then a contained keyword, then every message', () => {
    const fallback = listener({ id: 'any' });
    const contains = listener({ id: 'kw', matchMode: 'keyword', keywords: ['gia'] });
    const exact = listener({ id: 'ex', matchMode: 'exact', keywords: ['gia'] });
    const all = [fallback, contains, exact];

    expect(pickTrigger(all, 'Giá')?.id).toBe('ex');
    expect(pickTrigger(all, 'cho xin bảng giá')?.id).toBe('kw');
    expect(pickTrigger(all, 'xin chào')?.id).toBe('any');
    expect(pickTrigger([contains], 'xin chào')).toBeUndefined();
  });

  it('breaks ties by the oldest listener', () => {
    const older = listener({ id: 'old', createdAt: new Date(1) });
    const newer = listener({ id: 'new', createdAt: new Date(2) });
    expect(pickTrigger([newer, older], 'x')?.id).toBe('old');
  });

  it('detects listeners an event could not tell apart', () => {
    const any = { matchMode: 'any' as const, keywords: [] };
    expect(sharedCondition(any, any)).toBe('every message');
    expect(
      sharedCondition(
        { matchMode: 'keyword', keywords: ['gia', 'ship'] },
        { matchMode: 'keyword', keywords: ['ship'] },
      ),
    ).toBe('the keyword "ship"');
    expect(
      sharedCondition(
        { matchMode: 'keyword', keywords: ['gia'] },
        { matchMode: 'exact', keywords: ['gia'] },
      ),
    ).toBeNull();
    expect(sharedCondition(any, { matchMode: 'keyword', keywords: ['x'] })).toBeNull();
  });

  it('reads App Trigger nodes from a definition', () => {
    expect(
      findAppTriggerNodes(
        definition(
          { id: 'm', data: { key: 'trigger.manual' } },
          messengerTrigger({ match_mode: 'keyword', keywords: 'Giá, ship' }),
        ),
      ),
    ).toEqual([
      {
        nodeId: 'trigger',
        app: 'messenger',
        event: 'message',
        credentialId: PAGE_CREDENTIAL_ID,
        matchMode: 'keyword',
        rawMatchMode: 'keyword',
        keywords: ['gia', 'ship'],
      },
    ]);
    expect(findAppTriggerNodes(null)).toEqual([]);
  });
});

