import { randomBytes } from 'node:crypto';
import { BadRequestException } from '@nestjs/common';
import { EncryptionUtil } from '@app/shared/utils/encryption.util';
import { MetaOauthService } from '@app/integrations/application/meta-oauth.service';
import { OauthStateStore } from '@app/integrations/application/ports/oauth-state.store';
import { Connector } from '@app/connector/domain/entities/connector.entity';
import { ConnectorCredential } from '@app/connector/domain/entities/connector-credential.entity';
import { ConnectorAuthType } from '@app/connector/domain/enums/connector-auth-type.enum';
import { ConnectorRepository } from '@app/connector/domain/repositories/connector.repository';
import { ConnectorCredentialRepository } from '@app/connector/domain/repositories/connector-credential.repository';
import { FakeMetaGraph } from '@test/support/apps/fake-meta-graph';

class MemoryStates extends OauthStateStore {
  states = new Map<string, string>();
  save(state: string, userId: string) {
    this.states.set(state, userId);
    return Promise.resolve();
  }
  take(state: string) {
    const userId = this.states.get(state) ?? null;
    this.states.delete(state);
    return Promise.resolve(userId);
  }
}

class Connectors extends ConnectorRepository {
  findAllActive() {
    return Promise.resolve([]);
  }
  findByKey(key: string) {
    return Promise.resolve(
      key === 'messenger'
        ? new Connector('c-messenger', 'messenger', 'Messenger', ConnectorAuthType.API_KEY, {}, true)
        : null,
    );
  }
}

class Credentials extends ConnectorCredentialRepository {
  rows: ConnectorCredential[] = [];
  save(credential: ConnectorCredential) {
    this.rows = this.rows.map((row) => (row.id === credential.id ? credential : row));
    return Promise.resolve();
  }
  create(credential: ConnectorCredential) {
    const saved = new ConnectorCredential(
      `cred-${this.rows.length + 1}`,
      credential.connectorId,
      credential.ownerId,
      credential.name,
      credential.encryptedSecret,
    );
    this.rows.push(saved);
    return Promise.resolve(saved);
  }
  findByOwnerAndConnector(ownerId: string, connectorId: string) {
    return Promise.resolve(
      this.rows.filter((r) => r.ownerId === ownerId && r.connectorId === connectorId),
    );
  }
}

describe('MetaOauthService (Connect Facebook Page)', () => {
  const encryptionKey = randomBytes(32).toString('hex');
  const previousEnv = { ...process.env };
  let graph: FakeMetaGraph;
  let states: MemoryStates;
  let credentials: Credentials;
  let service: MetaOauthService;

  beforeEach(() => {
    process.env = {
      ...previousEnv,
      ENCRYPTION_KEY: encryptionKey,
      META_APP_ID: 'app-123',
      META_APP_SECRET: <REDACTED>,
      META_REDIRECT_URI: 'https://flow.example.com/api/integrations/meta/callback',
      META_GRAPH_VERSION: 'v23.0',
    };
    graph = new FakeMetaGraph();
    states = new MemoryStates();
    credentials = new Credentials();
    service = new MetaOauthService(graph, states, new Connectors(), credentials);
  });
  afterAll(() => {
    process.env = previousEnv;
  });

  const decrypt = (credential: ConnectorCredential) =>
    JSON.parse(EncryptionUtil.decrypt(credential.encryptedSecret, encryptionKey)) as Record<
      string,
      string
    >;

  async function signIn(userId = 'user-1') {
    const url = new URL(await service.authUrl(userId));
    return url;
  }

  it('builds the Facebook dialog URL with the Page scopes and a stored one-time state', async () => {
    const url = await signIn();
    expect(url.origin + url.pathname).toBe('https://www.facebook.com/v23.0/dialog/oauth');
    expect(url.searchParams.get('client_id')).toBe('app-123');
    expect(url.searchParams.get('redirect_uri')).toBe(process.env['META_REDIRECT_URI']);
    expect(url.searchParams.get('scope')).toBe(
      'pages_show_list,pages_messaging,pages_manage_metadata',
    );
    expect(states.states.get(url.searchParams.get('state')!)).toBe('user-1');
  });

  it('stores one connection per granted Page and subscribes each Page to the app', async () => {
