// Messenger end to end with a real HTTP server, Postgres, Redis and BullMQ.
// Only Facebook is replaced (META_GRAPH_API): connect a Page with OAuth, run a
// default flow and a keyword flow on it, reply through the Page.
import { createHmac } from 'node:crypto';
import { Test, TestingModule } from '@nestjs/testing';
import { ExecutionContext, INestApplication } from '@nestjs/common';
import request from 'supertest';
import { DesignerModule } from '@app/designer';
import { PrismaModule } from '@app/database';
