import { JwtAuthGuard } from '@app/auth/infrastructure/guards/jwt-auth.guard';
import { FakeMetaGraph } from '@test/support/apps/fake-meta-graph';

const APP_SECRET = <REDACTED>;
const VERIFY_TOKEN = <REDACTED>;

describe('App Trigger: Messenger (e2e)', () => {
  let app: INestApplication;
  let prisma: PrismaService;
  const graph = new FakeMetaGraph();
  const ownerId = '00000000-0000-0000-0000-000000000000';
  // Pages stay bound to earlier runs' workflows: use a fresh one every run.
  const pageId = `page-${Date.now()}`;
  const previousEnv = { ...process.env };

  const server = () =>
    app.getHttpServer() as unknown as Parameters<typeof request>[0];

  const postSigned = (body: unknown) => {
    const raw = JSON.stringify(body);
    return request(server())
      .post('/api/webhooks/messenger')
      .set('Content-Type', 'application/json')
      .set(
        'X-Hub-Signature-256',
        `sha256=${createHmac('sha256', APP_SECRET).update(raw).digest('hex')}`,
      )
      .send(raw);
  };

  const customerMessage = (mid: string, text: string, extra = {}) => ({
    object: 'page',
    entry: [
      {
        id: pageId,
        time: Date.now(),
        messaging: [
          {
            sender: { id: 'customer-42' },
            recipient: { id: pageId },
            timestamp: Date.now(),
            message: { mid, text, ...extra },
          },
        ],
      },
    ],
  });

  async function chatWorkflow(
    name: string,
    credentialId: string,
    trigger: Record<string, unknown>,
    replyText: string,
  ) {
    const created = await request(server())
      .post('/api/workflows')
      .send({ name, ownerId })
      .expect(201);
    const workflowId = created.body.data.id as string;
    await request(server())
      .put(`/api/workflows/${workflowId}/draft`)
      .send({
        definition: {
          nodes: [
            {
              id: 'chat',
              type: 'triggerNode',
              data: {
                key: 'trigger.app',
                name: 'Messenger',
                config: {
                  app: 'messenger',
                  event: 'message',
                  credential_id: credentialId,
                  ...trigger,
                },
              },
            },
            {
              id: 'reply',
              type: 'actionNode',
              data: {
                key: 'chat.reply',
                name: 'Reply',
                config: { text: replyText },
              },
            },
          ],
          edges: [{ id: 'e1', source: 'chat', target: 'reply' }],
        },
      })
      .expect(200);
    return workflowId;
  }

  const publish = (workflowId: string) =>
    request(server()).post(`/api/workflows/${workflowId}/versions`);

  async function waitForListener(workflowId: string) {
    for (let attempt = 0; attempt < 50; attempt += 1) {
      const row = await prisma.workflowTrigger.findFirst({
        where: { workflowId, isActive: true },
      });
      if (row) return row;
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    throw new Error('App trigger was never registered');
  }

  async function finished(executionId: string) {
    for (let attempt = 0; attempt < 100; attempt += 1) {
      const execution = await prisma.execution.findUnique({
        where: { id: executionId },
        include: { nodeLogs: { orderBy: { startedAt: 'asc' } } },
      });
      if (execution && execution.status !== 'RUNNING') return execution;
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    throw new Error(`execution ${executionId} did not finish`);
  }

  beforeAll(async () => {
    Object.assign(process.env, {
      META_APP_ID: 'e2e-app',
      META_APP_SECRET: <REDACTED>,
      META_VERIFY_TOKEN: <REDACTED>,
      META_REDIRECT_URI: 'http://localhost/api/integrations/meta/callback',
    });
    graph.pages = [{ id: pageId, name: 'Shop E2E', accessToken: <REDACTED> }];

    const moduleFixture: TestingModule = await Test.createTestingModule({
      imports: [
        PrismaModule,
        DesignerModule,
        ExecutionModule,
        TriggersModule,
        ConnectorModule,
        IntegrationsModule,
      ],
    })
      .overrideProvider(META_GRAPH_API)
      .useValue(graph)
      .overrideGuard(JwtAuthGuard)
      .useValue({
        canActivate: (context: ExecutionContext) => {
          const req = context.switchToHttp().getRequest();
          req.user = { id: ownerId, email: 'messenger-e2e@flowpilot.local' };
          return true;
        },
      })
      .compile();

    app = moduleFixture.createNestApplication({ rawBody: true });
    await app.init();
    prisma = app.get(PrismaService);
    await prisma.user.upsert({
      where: { id: ownerId },
      update: {},
      create: {
        id: ownerId,
        email: 'messenger-e2e@flowpilot.local',
        passwordHash: 'dummy',
        name: 'Messenger E2E User',
      },
    });
  });

  afterAll(async () => {
    process.env = previousEnv;
    await app.close();
  });

  it('answers the Meta verification challenge only with the right token', async () => {
    const ok = await request(server())
      .get('/api/webhooks/messenger')
      .query({
        'hub.mode': 'subscribe',
        'hub.verify_token': <REDACTED>,
        'hub.challenge': '12345',
      })
      .expect(200);
    expect(ok.text).toBe('12345');
    await request(server())
      .get('/api/webhooks/messenger')
      .query({ 'hub.mode': 'subscribe', 'hub.verify_token': <REDACTED> })
      .expect(403);
  });

  it('connects a Page with Facebook sign-in, routes by keyword and replies through the Page', async () => {
    // Connect Facebook Page: sign-in URL → Facebook redirects back with code + state.
    const auth = await request(server())
      .get('/api/integrations/meta/auth')
      .expect(200);
    const state = new URL(auth.body.url as string).searchParams.get('state');
    const callback = await request(server())
      .get('/api/integrations/meta/callback')
      .query({ code: 'fb-code', state })
      .expect(200);
    expect(callback.text).toContain('meta-oauth-success');
    expect(graph.subscribed).toEqual([
      { pageId, pageAccessToken: <REDACTED> },
    ]);
    const connected = await request(server())
      .get('/api/connectors/messenger/credentials')
      .expect(200);
    const credential = (
      connected.body.data as Array<{ id: string; name: string }>
    ).find((c) => c.name === 'Shop E2E');
    expect(credential).toBeDefined();
    const credentialId = credential!.id;
    // The state works once.
    await request(server())
      .get('/api/integrations/meta/callback')
      .query({ code: 'fb-code', state })
      .expect(400);

    // A default flow and a keyword flow on the same Page.
    const fallback = await chatWorkflow(
      'Default bot e2e',
      credentialId,
      {},
