import { useCallback, useEffect, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { triggerService } from '../services/trigger.service';
import { credentialKeys } from './useCredentials';

interface OAuthMessage {
  type?: unknown;
  connectorKey?: unknown;
  credentialIds?: unknown;
  message?: unknown;
}

// "Connect <app>" sign-in in a pop-up. The pop-up posts back
// { type: 'app-oauth-success' | 'app-oauth-error', connectorKey, ... }; the new
// connections are listed again and the first one is handed to onConnected.
export function useAppOAuth(
  connectorKey: string | undefined,
  startPath: string | undefined,
  onConnected: (credentialId: string) => void,
) {
  const queryClient = useQueryClient();
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!connectorKey) return;
    const handle = (event: MessageEvent<OAuthMessage>) => {
      if (event.data?.connectorKey !== connectorKey) return;
      if (event.data.type === 'app-oauth-success') {
        setPending(false);
        setError(null);
        void queryClient.invalidateQueries({ queryKey: credentialKeys.list(connectorKey) });
        const ids = event.data.credentialIds;
        if (Array.isArray(ids) && typeof ids[0] === 'string') onConnected(ids[0]);
      } else if (event.data.type === 'app-oauth-error') {
        setPending(false);
        setError(typeof event.data.message === 'string' ? event.data.message : 'Sign-in failed');
      }
    };
    window.addEventListener('message', handle);
    return () => window.removeEventListener('message', handle);
  }, [connectorKey, onConnected, queryClient]);

  const connect = useCallback(async () => {
    if (!startPath) return;
    setError(null);
    setPending(true);
    try {
      const url = await triggerService.oauthUrl(startPath);
      window.open(url, 'app-oauth', 'width=600,height=700');
    } catch (cause) {
      setPending(false);
      setError(cause instanceof Error ? cause.message : 'Sign-in could not start');
    }
  }, [startPath]);

  return { connect, pending, error };
}

