import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { TriggerApp } from '../../types/trigger.types';

const mockTriggerApi = vi.hoisted(() => ({
  list: vi.fn(),
  listApps: vi.fn(),
  oauthUrl: vi.fn(),
}));
const mockCredentialApi = vi.hoisted(() => ({
  list: vi.fn(),
  create: vi.fn(),
  listConnectors: vi.fn(),
}));
vi.mock('../../api/trigger.api', () => ({ triggerApi: mockTriggerApi }));
vi.mock('../../api/credential.api', () => ({ credentialApi: mockCredentialApi }));

import { AppTriggerFields } from './AppTriggerFields';
import { triggerService } from '../../services/trigger.service';

const webhook: TriggerApp = {
  key: 'webhook',
  name: 'Webhook',
  description: 'Start when an HTTP POST arrives',
  icon: 'webhook',
  events: [{ key: 'request', name: 'Incoming request', hasText: false }],
  connection: null,
  routing: 'token',
  canReply: false,
};
const messenger: TriggerApp = {
  key: 'messenger',
  name: 'Facebook Messenger',
  description: 'Start when a customer messages your Page',
  icon: 'message-circle',
  events: [{ key: 'message', name: 'New message', hasText: true }],
  connection: {
    connectorKey: 'messenger',
    oauth: { startPath: '/api/integrations/meta/auth', label: 'Connect Facebook Page' },
  },
  routing: 'connection',
  canReply: true,
};

function renderFields(config: Record<string, unknown>) {
  const onChange = vi.fn();
  const onReplaceConfig = vi.fn();
  render(
    <QueryClientProvider client={new QueryClient({ defaultOptions: { queries: { retry: false } } })}>
      <AppTriggerFields
        workflowId="workflow-1"
        nodeId="trigger-1"
        config={config}
        onChange={onChange}
        onReplaceConfig={onReplaceConfig}
      />
    </QueryClientProvider>,
  );
  return { onChange, onReplaceConfig };
}

describe('AppTriggerFields', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockTriggerApi.listApps.mockResolvedValue([webhook, messenger]);
    mockTriggerApi.list.mockResolvedValue([]);
    mockCredentialApi.list.mockResolvedValue([]);
  });
  afterEach(cleanup);

  it('offers sign-in for Messenger, and keywords when they are needed', async () => {
    const { onChange } = renderFields({
      app: 'messenger',
      event: 'message',
      match_mode: 'keyword',
      keywords: 'giá',
    });

    expect(await screen.findByRole('button', { name: 'Connect Facebook Page' })).toBeTruthy();
    expect(screen.getByRole('button', { name: 'Add manually' })).toBeTruthy();
    expect(screen.queryByText('Webhook URL')).toBeNull();

    const keywords = screen.getByLabelText('Keywords') as HTMLInputElement;
    expect(keywords.value).toBe('giá');
    fireEvent.change(keywords, { target: { value: 'giá, ship' } });
    expect(onChange).toHaveBeenCalledWith('keywords', 'giá, ship');
  });

  it('opens the sign-in pop-up and selects the connection it reports back', async () => {
    mockTriggerApi.oauthUrl.mockResolvedValue('https://www.facebook.com/dialog/oauth?x');
    const open = vi.spyOn(window, 'open').mockReturnValue({ closed: false } as Window);
    const { onChange } = renderFields({ app: 'messenger', event: 'message' });

    fireEvent.click(await screen.findByRole('button', { name: 'Connect Facebook Page' }));
    await waitFor(() =>
      expect(open).toHaveBeenCalledWith(
        'https://www.facebook.com/dialog/oauth?x',
        'app-oauth',
        expect.any(String),
      ),
    );
    expect(mockTriggerApi.oauthUrl).toHaveBeenCalledWith('/api/integrations/meta/auth');

    act(() => {
      window.dispatchEvent(
        new MessageEvent('message', {
          data: { type: 'app-oauth-success', connectorKey: 'messenger', credentialIds: ['cred-9'] },
        }),
      );
    });
    expect(onChange).toHaveBeenCalledWith('credential_id', 'cred-9');
    open.mockRestore();
  });

  it('shows the webhook URL field and no condition for the Webhook app', async () => {
    renderFields({ app: 'webhook', event: 'request' });
    expect(await screen.findByText('Webhook URL')).toBeTruthy();
    expect(screen.queryByText('Run when')).toBeNull();
    expect(screen.queryByRole('button', { name: /Connect/ })).toBeNull();
  });
});

describe('triggerService.configForApp', () => {
  it('picks the single event and drops what belonged to the previous app', () => {
    expect(
      triggerService.configForApp(
        {
          app: 'messenger',
          event: 'message',
          credential_id: 'c',
          match_mode: 'keyword',
          keywords: 'x',
        },
        webhook,
      ),
    ).toEqual({ app: 'webhook', event: 'request', match_mode: 'any' });
  });
});

