import { createHmac, timingSafeEqual } from 'node:crypto';
import { AppDefinition, AppEvent, IncomingAppRequest } from '../app-definition';
import { MetaGraphApi } from './meta-graph.api';

interface MessagingEvent {
  sender?: { id?: unknown };
  recipient?: { id?: unknown };
  timestamp?: unknown;
  message?: {
    mid?: unknown;
    text?: unknown;
    is_echo?: unknown;
    attachments?: Array<{ type?: unknown; payload?: { url?: unknown } }>;
  };
}

// Facebook Page messages. FlowPilot runs ONE Meta app for everybody: its
// secret, verify token and webhook URL are server settings (.env); a user
// only connects their Page.
export function createMessengerApp(graph: MetaGraphApi): AppDefinition {
  return {
    key: 'messenger',
    name: 'Facebook Messenger',
    description: 'Start when a customer messages your Facebook Page',
    icon: 'message-circle',
    events: [{ key: 'message', name: 'New message', hasText: true }],
    connection: {
      connectorKey: 'messenger',
      oauth: {
        startPath: '/api/integrations/meta/auth',
        label: 'Connect Facebook Page',
      },
    },
    routing: 'connection',
    ackStatus: 200,

    routingKeyFromSecret(secret) {
      const pageId = secret.page_id;
      return typeof pageId === 'string' && pageId.trim() ? pageId.trim() : null;
    },

    // Meta calls this once when the webhook is set up in the app dashboard.
    handshake(request) {
      const expected = process.env['META_VERIFY_TOKEN'];
      return request.query['hub.mode'] === 'subscribe' &&
        !!expected &&
        request.query['hub.verify_token'] === expected
        ? String(request.query['hub.challenge'] ?? '')
        : null;
    },

    verify(request) {
      return isValidMetaSignature(
        request.rawBody,
        header(request, 'x-hub-signature-256'),
        process.env['META_APP_SECRET'],
      );
    },

    parse: (request) => parseMessengerEvents(request.body),

    replyMaxLength: 2000,

    async reply(secret, recipientId, text) {
      const token = <REDACTED>;
      if (typeof token !== 'string' || !token) {
        throw new Error('The Facebook Page connection has no access token');
      }
      return graph.sendText(token, recipientId, text);
    },
  };
}

// X-Hub-Signature-256 = "sha256=" + HMAC-SHA256 of the exact request bytes,
// keyed with the app secret.
export function isValidMetaSignature(
  rawBody: Buffer | undefined,
  signature: string | undefined,
  appSecret: <REDACTED> | undefined,
): boolean {
  if (!rawBody || !signature || !appSecret) return false;
  const expected = Buffer.from(
    `sha256=${createHmac('sha256', appSecret).update(rawBody).digest('hex')}`,
  );
  const received = Buffer.from(signature.trim());
  return (
    received.length === expected.length && timingSafeEqual(received, expected)
  );
}

// One event per message a customer sent. Echoes (messages the Page itself
// sent, including the bot's replies), deliveries and reads are dropped, so a
// reply never starts a workflow again.
export function parseMessengerEvents(body: unknown): AppEvent[] {
  const payload = body as { object?: unknown; entry?: unknown } | null;
  if (payload?.object !== 'page' || !Array.isArray(payload.entry)) return [];

  const events: AppEvent[] = [];
  for (const entry of payload.entry as Array<{
    id?: unknown;
    messaging?: unknown;
  }>) {
    if (typeof entry?.id !== 'string' || !Array.isArray(entry.messaging)) {
      continue;
    }
    for (const event of entry.messaging as MessagingEvent[]) {
      const message = event?.message;
      const senderId = event?.sender?.id;
      if (
        !message ||
        message.is_echo === true ||
        typeof message.mid !== 'string' ||
        typeof senderId !== 'string'
      ) {
        continue;
      }
      const text = typeof message.text === 'string' ? message.text : '';
      events.push({
        routingKey: entry.id,
        eventType: 'message',
        eventId: message.mid,
        text,
        item: {
          json: {
            app: 'messenger',
            message_id: message.mid,
            sender_id: senderId,
            page_id: entry.id,
            text,
            attachments: (message.attachments ?? []).map((attachment) => ({
              type:
                typeof attachment?.type === 'string' ? attachment.type : null,
              url:
                typeof attachment?.payload?.url === 'string'
                  ? attachment.payload.url
                  : null,
            })),
            timestamp:
              typeof event.timestamp === 'number'
                ? new Date(event.timestamp).toISOString()
                : null,
            conversation: { app: 'messenger', recipient_id: senderId },
            raw: event,
          },
        },
      });
    }
  }
  return events;
}

function header(request: IncomingAppRequest, name: string): string | undefined {
  const value = request.headers[name];
  return Array.isArray(value) ? value[0] : value;
}

import { createHmac } from 'node:crypto';
import { AxiosError, AxiosHeaders } from 'axios';
import { IncomingAppRequest } from '@app/apps';
import { webhookApp } from '@app/apps/webhook/webhook.app';
import {
  createMessengerApp,
  isValidMetaSignature,
  parseMessengerEvents,
} from '@app/apps/messenger/messenger.app';
import { toAppApiError } from '@app/apps/messenger/meta-graph.api';
import { FakeMetaGraph } from '@test/support/apps/fake-meta-graph';

const request = (
  overrides: Partial<IncomingAppRequest> = {},
): IncomingAppRequest => ({
  method: 'POST',
  query: {},
  headers: {},
  body: {},
  ...overrides,
});

const textEvent = (overrides: Record<string, unknown> = {}) => ({
  sender: { id: 'customer-1' },
  recipient: { id: 'page-1' },
  timestamp: Date.UTC(2026, 9, 29, 8, 0, 0),
  message: { mid: 'm_1', text: 'Còn size M không shop?' },
  ...overrides,
});
const pageBody = (pageId: string, ...messaging: unknown[]) => ({
  object: 'page',
  entry: [{ id: pageId, time: 1, messaging }],
});

describe('webhook app', () => {
  it('turns a call to a token into one request event, hiding caller credentials', () => {
    const [event] = webhookApp.parse(
      request({
        token: <REDACTED>,
        body: { email: 'a@b.c' },
        query: { source: 'form' },
        headers: {
          'Content-Type': 'application/json',
          authorization: 'Bearer <REDACTED>',
          cookie: <REDACTED>,
          'x-api-key': <REDACTED>,
          'idempotency-key': ' order-42 ',
        },
      }),
    );

    expect(event).toMatchObject({
      routingKey: 'token-1',
      eventType: 'request',
      eventId: 'order-42',
    });
    expect(event.item.json).toMatchObject({
      body: { email: 'a@b.c' },
      query: { source: 'form' },
      headers: {
        'content-type': 'application/json',
        'idempotency-key': ' order-42 ',
      },
    });
    expect(JSON.stringify(event.item.json)).not.toContain('secret');
    expect(event.item.json.conversation).toBeUndefined();
  });

  it('has nothing to parse without a token and cannot reply', () => {
    expect(webhookApp.parse(request())).toEqual([]);
    expect(webhookApp.reply).toBeUndefined();
    expect(webhookApp.routing).toBe('token');
  });
});

describe('messenger app', () => {
  const graph = new FakeMetaGraph();
  const app = createMessengerApp(graph);
  const previousEnv = { ...process.env };
  beforeEach(() => {
    process.env['META_APP_SECRET'] = 'app-secret';
    process.env['META_VERIFY_TOKEN'] = 'verify-me';
  });
  afterAll(() => {
    process.env = previousEnv;
  });

  const signed = (body: unknown, secret = <REDACTED> => {
    const raw = Buffer.from(JSON.stringify(body));
    return request({
      body,
      rawBody: raw,
      headers: {
        'x-hub-signature-256': `sha256=${createHmac('sha256', secret).update(raw).digest('hex')}`,
      },
    });
  };

  it('answers the Meta verification challenge only for the right token', () => {
    const query = (token: <REDACTED> => ({
      'hub.mode': 'subscribe',
      'hub.verify_token': <REDACTED>,
      'hub.challenge': '123',
    });
    expect(
      app.handshake!(request({ method: 'GET', query: query('verify-me') })),
    ).toBe('123');
    expect(
      app.handshake!(request({ method: 'GET', query: query('nope') })),
    ).toBeNull();
  });

  it('accepts only calls signed with the app secret over the exact body', () => {
    const body = pageBody('page-1', textEvent());
    expect(app.verify(signed(body))).toBe(true);
    expect(app.verify(signed(body, 'other-secret'))).toBe(false);
    const tampered = signed(body);
    tampered.rawBody = Buffer.from(
      tampered.rawBody!.toString().replace('M', 'L'),
    );
    expect(app.verify(tampered)).toBe(false);
    expect(app.verify(request({ body }))).toBe(false);
    expect(
      isValidMetaSignature(Buffer.from('x'), 'sha256=short', 'app-secret'),
    ).toBe(false);
  });

  it('turns each customer message into an event with the conversation to answer', () => {
    const [event] = parseMessengerEvents(
      pageBody(
        'page-1',
        textEvent({
          message: {
            mid: 'm_1',
            text: 'Ảnh đây',
            attachments: [
              { type: 'image', payload: { url: 'https://x/y.jpg' } },
            ],
          },
        }),
      ),
    );

    expect(event).toMatchObject({
      routingKey: 'page-1',
      eventType: 'message',
      eventId: 'm_1',
      text: 'Ảnh đây',
    });
    expect(event.item.json).toMatchObject({
      app: 'messenger',
      sender_id: 'customer-1',
      page_id: 'page-1',
      attachments: [{ type: 'image', url: 'https://x/y.jpg' }],
      timestamp: '2026-10-29T08:00:00.000Z',
      conversation: { app: 'messenger', recipient_id: 'customer-1' },
    });
  });

  it('drops echoes of the Page own messages, deliveries, reads and other objects', () => {
    expect(
      parseMessengerEvents(
        pageBody(
          'page-1',
          textEvent({ message: { mid: 'm_2', text: 'bot', is_echo: true } }),
          { sender: { id: 'c' }, delivery: { mids: ['m_1'] } },
          { sender: { id: 'c' }, read: { watermark: 1 } },
        ),
      ),
    ).toEqual([]);
    expect(parseMessengerEvents({ object: 'instagram', entry: [] })).toEqual(
      [],
    );
    expect(parseMessengerEvents(null)).toEqual([]);
  });

  it('routes by the page id of the connection and replies with its token', async () => {
    expect(app.routingKeyFromSecret!({ page_id: ' page-1 ' })).toBe('page-1');
    expect(app.routingKeyFromSecret!({})).toBeNull();

    await app.reply!(
      { page_id: 'page-1', page_access_token: <REDACTED> },
      'customer-1',
      'Hello',
    );
    expect(graph.sent).toEqual([
      { pageAccessToken: <REDACTED>, recipientId: 'customer-1', text: 'Hello' },
    ]);
    await expect(app.reply!({ page_id: 'page-1' }, 'c', 'x')).rejects.toThrow(
      'no access token',
    );
  });
});

describe('toAppApiError', () => {
  const graphError = (status: number, error: Record<string, unknown>) =>
    new AxiosError('Request failed', 'ERR_BAD_REQUEST', undefined, undefined, {
      status,
      statusText: '',
      headers: {},
      config: { headers: new AxiosHeaders() },
      data: { error },
    });

  it('explains the 24-hour window, unavailable people and expired connections without retrying', () => {
    const window = toAppApiError(
      graphError(400, { code: 10, error_subcode: 2018278 }),
    );
    expect(window.message).toContain('24 hours');
    expect(window.retryable).toBe(false);
    expect(toAppApiError(graphError(400, { code: 551 })).message).toContain(
      'not available',
    );
    expect(toAppApiError(graphError(400, { code: 190 })).message).toContain(
      'connect the Page again',
    );
  });

  it('retries 429, 5xx, Graph rate limits and timeouts only', () => {
    expect(toAppApiError(graphError(429, {})).retryable).toBe(true);
    expect(toAppApiError(graphError(503, {})).retryable).toBe(true);
    expect(toAppApiError(graphError(400, { code: 613 })).retryable).toBe(true);
    expect(
      toAppApiError(new AxiosError('timeout', 'ECONNABORTED')).retryable,
    ).toBe(true);
    expect(
      toAppApiError(graphError(400, { code: 100, message: 'bad' })).retryable,
    ).toBe(false);
  });
});

