import { useState } from 'react';
import { Check, Copy, Zap } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useTriggerApps, useWorkflowTriggers } from '../hooks/useWorkflowTriggers';
import { triggerService } from '../services/trigger.service';

interface AppTriggerInfoProps {
  workflowId: string;
  versionId: string;
  nodeId: string;
  appKey: unknown;
}

// Shown instead of the Run button: an App Trigger version runs by itself when
// its app sends an event (apps routed by URL show that URL).
export function AppTriggerInfo({ workflowId, versionId, nodeId, appKey }: AppTriggerInfoProps) {
  const { data: triggers, isLoading } = useWorkflowTriggers(workflowId);
  const { data: apps = [] } = useTriggerApps();
  const [copied, setCopied] = useState(false);
  const appName = apps.find((app) => app.key === appKey)?.name ?? 'the app';
  const trigger = triggerService.findForNode(triggers, nodeId);
  const isCurrent = trigger?.workflowVersionId === versionId;
  const url = isCurrent ? trigger?.webhookUrl : null;

  const copy = () => {
    if (!url) return;
    navigator.clipboard
      .writeText(url)
      .then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      })
      .catch(() => undefined);
  };

  return (
    <div className="w-full max-w-md space-y-2 rounded-xl border border-border bg-muted/40 p-4">
      <div className="flex items-center gap-2 text-sm font-semibold">
        <Zap className="size-4 text-primary" />
        Tự chạy khi có sự kiện từ {appName}
      </div>
      {isLoading ? (
        <p className="text-xs text-muted-foreground">Đang tải…</p>
      ) : !isCurrent ? (
        <p className="text-xs text-muted-foreground">
          Chỉ phiên bản đang chạy (bản publish mới nhất) nhận sự kiện. Phiên bản này không nhận.
        </p>
      ) : url ? (
        <>
          <div className="flex gap-2">
            <Input
              readOnly
              value={url}
              aria-label="Webhook URL"
              className="font-mono text-xs"
              onFocus={(e) => e.target.select()}
            />
            <Button
              type="button"
              variant="outline"
              size="icon"
              onClick={copy}
              aria-label="Sao chép Webhook URL"
            >
              {copied ? <Check className="size-4" /> : <Copy className="size-4" />}
            </Button>
          </div>
          <p className="text-xs text-muted-foreground">
            Gửi <code className="font-mono">POST</code> kèm JSON tới URL này; workflow chạy nền.
          </p>
        </>
      ) : (
        <p className="text-xs text-muted-foreground">
          Phiên bản này đang lắng nghe; workflow chạy nền mỗi khi có sự kiện khớp điều kiện.
        </p>
      )}
    </div>
  );
}

