// The server explains why sign-in cannot start (e.g. not configured); axios'
// own message ("Request failed with status code 400") does not.
function serverMessage(cause: unknown): string {
  if (isAxiosError<{ message?: unknown }>(cause)) {
    const message = cause.response?.data?.message;
    if (typeof message === 'string' && message) return message;
  }
  return cause instanceof Error ? cause.message : 'Sign-in could not start';
}
